-- =============================================================================
-- Studuel — Migration 574 : SPORT 1re — LE CAHIER D'EXERCICES ET LES CONTRÔLES BLANCS
-- de la culture sportive (14/10/2026, docs/CADRAGE-SPORT.md). Deux parties générées,
-- collées à la suite : le cahier (scripts/exercices-sql.ts) puis les contrôles
-- (scripts/controles-sql.ts). À exécuter APRÈS la migration de cours de ce niveau
-- (les chapitres doivent exister : une ligne dont le chapitre manque est sautée).
-- =============================================================================

-- =============================================================================
-- 574 — LE CAHIER D'EXERCICES DE 1RE
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 574 --niveau 1re --fichiers sport.culture > supabase/contenu/574_exercices_1re.sql
--
-- 30 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (0/0/5 gemmes depuis la 557, 20/35/50 XP), réglables ensuite en base.
--
--   sport.culture           30 exercices · 10 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('b6124e13-4abd-5a43-8fbb-7e9992ff56b7'::uuid, 1, 1, 0, 20, 3,
   $ex${"titre":"Trois épreuves, trois moteurs","competence":"lire-tableau","situation":"Au meeting du lycée, Sofia assiste à trois courses : un sprint, un tour de piste et un fond. Le tableau donne la durée approximative des records masculins : on ne court pas ces épreuves avec le même « moteur ».","documents":[{"id":"records","type":"tableau","titre":"Trois épreuves d’athlétisme","source":"Durées arrondies (ordres de grandeur) des records du monde masculins.","colonnes":["Épreuve","Durée du record"],"enteteLignes":true,"lignes":[["100 m","10 s"],["400 m","43 s"],["10 000 m","26 min"]]}],"questions":[{"enonce":"Touche la **durée du record du 400 m**.","aide":"Cherche la ligne « 400 m », puis la colonne des durées.","type":"zone","document":"records","multiple":false},{"enonce":"Relie chaque épreuve à la filière énergétique qui domine.","aide":"Compare la durée de chaque épreuve aux seuils du cours : 10 secondes et 2 minutes.","type":"association","gauche":[{"id":"g0","texte":"100 m"},{"id":"g1","texte":"400 m"},{"id":"g2","texte":"10 000 m"}],"droite":[{"id":"d0","texte":"Anaérobie lactique"},{"id":"d1","texte":"Aérobie"},{"id":"d2","texte":"Anaérobie alactique"}]},{"enonce":"Pourquoi un sprinteur ne peut-il pas tenir sa vitesse maximale pendant 2 minutes ?","aide":"Plus un effort est intense, plus il est court : quelle filière est puissante mais à stock limité ?","type":"choix","options":[{"id":"a","texte":"Parce qu’il oublie de respirer"},{"id":"b","texte":"Parce que ses muscles n’ont plus d’ATP du tout"},{"id":"c","texte":"Parce que le lactate est un poison"},{"id":"d","texte":"Parce que la filière très puissante qu’il utilise s’épuise en une dizaine de secondes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Le record du 400 m dure environ **43 secondes** : on est entre 10 s et 2 min, la zone où la filière lactique domine."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**100 m** (≈ 10 s) : phosphocréatine, filière alactique. **400 m** (≈ 43 s) : glycolyse sans oxygène, filière lactique. **10 000 m** (≈ 26 min) : oxygène, filière aérobie."},{"cle":{"type":"choix","ids":["d"]},"explication":"La filière alactique est **très puissante, mais son stock de phosphocréatine tient une dizaine de secondes**. Puissance et durée ne vont jamais ensemble."}]$ex$::jsonb),
  ('b6124e13-4abd-5a43-8fbb-7e9992ff56b7'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"La part de l’oxygène","competence":"lire-graphique","situation":"Un physiologiste mesure, pour des efforts de plus en plus longs, la part de l’énergie fournie par la filière aérobie. Le reste vient des deux filières anaérobies. À toi de lire la courbe.","documents":[{"id":"aerobie","type":"graphique","forme":"courbe","titre":"Part de l’énergie fournie par la filière aérobie","source":"Valeurs arrondies, ordres de grandeur écrits pour l’exercice.","categories":["10 s","30 s","1 min","2 min","4 min","10 min","30 min"],"series":[{"nom":"Filière aérobie","valeurs":[10,30,50,65,80,90,98],"teinte":"turquoise"}],"axeY":{"titre":"Part de l’énergie","unite":"%","min":0,"max":100,"pas":20},"axeX":{"titre":"Durée de l’effort"},"valeurs":false}],"questions":[{"enonce":"Quelle part de l’énergie vient de la filière aérobie pour un effort de **2 minutes** ?","aide":"Repère « 2 min » sur l’axe horizontal, monte jusqu’à la courbe, lis à gauche.","type":"nombre","unite":"%"},{"enonce":"Pour un effort de **30 secondes**, quelle part de l’énergie fournissent les deux filières anaérobies réunies ?","aide":"L’aérobie et les deux anaérobies font 100 % à elles trois.","type":"nombre","unite":"%"},{"enonce":"Touche la durée pour laquelle l’énergie est **moitié aérobie, moitié anaérobie**.","aide":"Cherche le point de la courbe à 50 %.","type":"zone","document":"aerobie","multiple":false},{"enonce":"À 10 secondes, la filière aérobie fournit déjà environ 10 % de l’énergie. Que montre ce point ?","aide":"Même sur un effort très court, la courbe n’est pas à zéro.","type":"choix","options":[{"id":"a","texte":"Le lactate est un poison"},{"id":"b","texte":"Les filières ne s’allument pas comme des interrupteurs : elles tournent toujours ensemble"},{"id":"c","texte":"Le sprinteur n’utilise jamais la phosphocréatine"},{"id":"d","texte":"La filière aérobie est la plus puissante"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":65,"tolerance":3},"affichage":"65 %","explication":"À 2 minutes, la filière aérobie fournit environ **65 %** de l’énergie : elle a déjà pris le relais, sans que les autres s’éteignent."},{"cle":{"type":"nombre","valeur":70,"tolerance":3},"affichage":"70 %","explication":"L’aérobie fournit 30 % : il reste 100 − 30 = **70 %** pour les filières alactique et lactique."},{"cle":{"type":"zone","ids":["k2"]},"explication":"À **1 minute**, la courbe atteint 50 % : c’est le moment où les deux familles de filières pèsent autant."},{"cle":{"type":"choix","ids":["b"]},"explication":"Aucune filière n’est jamais à 0 : elles **se chevauchent en permanence**, et c’est l’intensité et la durée qui décident de celle qui domine."}]$ex$::jsonb),
  ('b6124e13-4abd-5a43-8fbb-7e9992ff56b7'::uuid, 3, 3, 5, 50, 5,
   $ex${"titre":"La semaine de Nora, spécialiste du 400 m","competence":"analyser-document","situation":"Nora prépare le 400 m. Son entraîneur lui propose trois séances types. Croise le programme de la semaine avec les règles d’entraînement de chaque filière.","documents":[{"id":"semaine","type":"tableau","titre":"Les trois séances de la semaine","source":"Programme écrit pour l’exercice.","colonnes":["Jour","Contenu de la séance"],"enteteLignes":true,"lignes":[["Lundi","6 × 60 m départ arrêté, 3 min de récupération entre chaque course"],["Mercredi","50 min de footing à allure facile"],["Vendredi","6 × 1 min très rapide, 1 min de marche entre chaque"]]},{"id":"regles","type":"tableau","titre":"Comment entraîner chaque filière","source":"Fiche écrite pour l’exercice.","colonnes":["Filière","Principe"],"enteteLignes":true,"lignes":[["Alactique","Efforts très courts et maximaux, récupération complète"],["Lactique","Séries de 30 s à 2 min à forte intensité, récupération incomplète"],["Aérobie","Du volume : longues séances à allure modérée"]]}],"questions":[{"enonce":"Touche la séance qui construit surtout le **moteur aérobie** de Nora.","aide":"Cherche la séance longue, à allure facile.","type":"zone","document":"semaine","multiple":false},{"enonce":"Classe chaque séance selon la filière qu’elle sollicite surtout.","aide":"Compare la durée de l’effort et la récupération avec les principes du deuxième tableau.","type":"categories","categories":[{"id":"c0","texte":"Alactique"},{"id":"c1","texte":"Lactique"},{"id":"c2","texte":"Aérobie"}],"items":[{"id":"i0","texte":"Mercredi : 50 min de footing facile"},{"id":"i1","texte":"Lundi : 6 × 60 m, 3 min de récupération"},{"id":"i2","texte":"Vendredi : 6 × 1 min rapide, 1 min de marche"}]},{"enonce":"Lundi, Nora court 6 fois 60 m avec 3 min de récupération **entre** chaque course. Combien de minutes de récupération au total ?","aide":"Entre 6 courses, il y a combien de pauses ?","type":"nombre","unite":"min"},{"enonce":"Pourquoi la récupération est-elle longue entre deux sprints du lundi ?","aide":"Quelle filière a un petit stock qui ne se refait qu’au repos ?","type":"choix","options":[{"id":"a","texte":"Pour reconstituer le stock de phosphocréatine et rester explosive"},{"id":"b","texte":"Pour que le lactate disparaisse complètement"},{"id":"c","texte":"Parce que l’aérobie met 3 minutes à démarrer"},{"id":"d","texte":"Pour s’habituer à courir lentement"}],"multiple":false},{"enonce":"Quelle séance est la plus proche de l’effort d’un 400 m (environ 50 s) ?","aide":"Un 400 m dure entre 10 s et 2 min : quelle filière ? quelle séance la travaille ?","type":"choix","options":[{"id":"a","texte":"Le lundi : sprints de 60 m"},{"id":"b","texte":"Aucune des trois"},{"id":"c","texte":"Le mercredi : footing de 50 min"},{"id":"d","texte":"Le vendredi : séries d’une minute à forte intensité"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Le **footing de 50 minutes** à allure facile est du volume : c’est exactement le travail de la filière aérobie."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c1"}},"explication":"Lundi : efforts très courts et récupération longue → **alactique**. Vendredi : efforts de 1 min, récupération incomplète → **lactique**. Mercredi : volume → **aérobie**."},{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15 min","explication":"Il y a **5 pauses** entre 6 courses : 5 × 3 = **15 minutes**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le stock de phosphocréatine ne se reconstitue qu’au repos : **une récupération complète** permet de rester explosive à chaque départ."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le 400 m est un effort **lactique** : les séries d’environ une minute du vendredi le reproduisent le mieux."}]$ex$::jsonb),
  ('18025266-7610-5538-8081-e77ac4ab711c'::uuid, 1, 1, 0, 20, 3,
   $ex${"titre":"La semaine de Malik","competence":"lire-tableau","situation":"Malik, 15 ans, débute la course à pied. Son entraîneur lui a écrit une semaine type de trois séances. Lis son programme.","documents":[{"id":"semaine","type":"tableau","titre":"La semaine type de Malik","source":"Programme écrit pour l’exercice.","colonnes":["Jour","Séance","Durée"],"enteteLignes":true,"lignes":[["Lundi","Endurance fondamentale, allure facile","40 min"],["Mardi","Repos","—"],["Mercredi","Fractionné : répétitions rapides et récupérations","35 min"],["Jeudi","Repos","—"],["Vendredi","Repos","—"],["Samedi","Renforcement : gainage et squats","30 min"],["Dimanche","Repos","—"]]}],"questions":[{"enonce":"Touche la séance de **fractionné**.","aide":"Cherche le mot « Fractionné » dans la colonne des séances.","type":"zone","document":"semaine","multiple":false},{"enonce":"Combien de jours de **repos** compte la semaine de Malik ?","aide":"Compte les lignes « Repos ».","type":"nombre"},{"enonce":"En choisissant trois séances par semaine, quel réglage de la charge Malik fixe-t-il ?","aide":"Quel réglage compte le nombre de séances ?","type":"choix","options":[{"id":"a","texte":"La fréquence"},{"id":"b","texte":"Le volume"},{"id":"c","texte":"L’intensité"},{"id":"d","texte":"La densité"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Le fractionné a lieu le **mercredi** : des répétitions rapides entrecoupées de récupération, pour gagner en vitesse."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"Mardi, jeudi, vendredi et dimanche : **4 jours de repos**. Ils ne sont pas perdus : c’est là que le corps progresse."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le nombre de séances par semaine est la **fréquence**. Le volume mesure la quantité de travail, l’intensité sa difficulté, la densité le rapport effort/repos."}]$ex$::jsonb),
  ('18025266-7610-5538-8081-e77ac4ab711c'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"Léna et Tom, six semaines de course","competence":"calculer","situation":"Léna et Tom préparent la même course. Léna ajoute 2 km par semaine. Tom, pressé, fait grimper son kilométrage beaucoup plus vite, puis se blesse au genou à la semaine 5 et doit réduire. Le graphique donne leur volume hebdomadaire.","documents":[{"id":"volume","type":"graphique","forme":"barres","titre":"Kilomètres courus par semaine","source":"Chiffres imaginés pour l’exercice.","categories":["S1","S2","S3","S4","S5","S6"],"series":[{"nom":"Léna","valeurs":[20,22,24,26,28,30],"teinte":"violet"},{"nom":"Tom","valeurs":[20,30,40,50,35,20],"teinte":"corail"}],"axeY":{"titre":"Volume","unite":"km","min":0,"max":60,"pas":10},"axeX":{"titre":"Semaine"},"valeurs":false}],"questions":[{"enonce":"De quel pourcentage Tom a-t-il augmenté son volume entre S1 et S2 ?","aide":"Il passe de 20 à 30 km. Calcule la hausse (10 km) puis rapporte-la à 20 km.","type":"nombre","unite":"%"},{"enonce":"Touche la **première semaine** où le volume de Tom diminue.","aide":"Cherche la semaine où la barre corail est plus basse que la précédente.","type":"zone","document":"volume","multiple":false},{"enonce":"À la semaine 6, Léna court 30 km. En appliquant +10 %, combien de kilomètres peut-elle courir à la semaine 7 ?","aide":"10 % de 30 km, c’est 3 km.","type":"nombre","unite":"km"},{"enonce":"Quel principe d’entraînement Tom n’a-t-il pas respecté ?","aide":"Regarde l’ampleur des hausses de Tom de S1 à S4.","type":"choix","options":[{"id":"a","texte":"La spécificité"},{"id":"b","texte":"La variété"},{"id":"c","texte":"La réversibilité"},{"id":"d","texte":"La surcharge progressive (environ 10 % par semaine)"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":50,"tolerance":0},"affichage":"50 %","explication":"La hausse est de 10 km sur 20 km, soit **50 %**. Le cours recommande environ 10 % par semaine : Tom a multiplié la dose par cinq."},{"cle":{"type":"zone","ids":["k4"]},"explication":"À la **semaine 5**, Tom passe de 50 à 35 km : c’est la blessure au genou qui le force à lever le pied."},{"cle":{"type":"nombre","valeur":33,"tolerance":0},"affichage":"33 km","explication":"30 × 1,10 = **33 km**. Une surcharge de 10 % par semaine suffit à progresser sans se blesser."},{"cle":{"type":"choix","ids":["d"]},"explication":"Tom a ajouté **10 km par semaine** au lieu d’environ 10 % : son corps n’a pas eu le temps de s’adapter, d’où la blessure."}]$ex$::jsonb),
  ('18025266-7610-5538-8081-e77ac4ab711c'::uuid, 3, 3, 5, 50, 4,
   $ex${"titre":"Le carnet de Camille","competence":"raisonner","situation":"Camille, 16 ans, a décidé de « tout donner » avant les championnats scolaires. Elle note chaque semaine ses séances, sa forme et sa fréquence cardiaque au repos (FC). Son entraîneur lui a remis une fiche sur le surentraînement.","documents":[{"id":"carnet","type":"tableau","titre":"Le carnet de Camille","source":"Chiffres imaginés pour l’exercice.","colonnes":["Semaine","Séances","Forme ressentie (/10)","FC au repos (bpm)","Sommeil"],"enteteLignes":true,"lignes":[["S1",3,8,54,"bon"],["S2",4,7,55,"bon"],["S3",5,5,59,"haché"],["S4",6,3,63,"mauvais"]]},{"id":"signes","type":"texte","genre":"consigne","titre":"Les signes du surentraînement","auteur":"Fiche d’entraînement écrite pour l’exercice","blocs":["Tu en fais trop si tu es fatigué en permanence, si tes performances stagnent ou baissent, si ton sommeil se dégrade, si tu es irritable ou si ton cœur bat plus vite au repos.","La réponse n’est pas de forcer : c’est de lever le pied quelques jours."]}],"questions":[{"enonce":"Touche la **fréquence cardiaque au repos** de Camille à la semaine 4.","aide":"Ligne S4, colonne « FC au repos ».","type":"zone","document":"carnet","multiple":false},{"enonce":"De combien de battements par minute sa FC au repos a-t-elle augmenté entre S1 et S4 ?","aide":"Fais la différence entre les valeurs de S4 et de S1.","type":"nombre","unite":"bpm"},{"enonce":"Trie ces éléments du carnet : signe d’alerte ou cause possible ?","aide":"Les signes sont ce que le corps répond ; la cause est ce que Camille a changé.","type":"categories","categories":[{"id":"c0","texte":"Signe d’alerte"},{"id":"c1","texte":"Cause possible"}],"items":[{"id":"i0","texte":"Séances qui passent de 3 à 6"},{"id":"i1","texte":"Forme ressentie qui chute"},{"id":"i2","texte":"FC au repos qui monte"},{"id":"i3","texte":"Volume doublé en trois semaines"},{"id":"i4","texte":"Sommeil qui se dégrade"}]},{"enonce":"Que doit faire Camille ?","aide":"Relis la dernière phrase de la fiche.","type":"choix","options":[{"id":"a","texte":"S’arrêter complètement pendant trois mois"},{"id":"b","texte":"Ne rien changer : la fatigue passera"},{"id":"c","texte":"Lever le pied quelques jours, puis reprendre progressivement"},{"id":"d","texte":"Ajouter une septième séance pour compenser"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c3"]},"explication":"À la semaine 4, sa FC au repos est de **63 bpm**, contre 54 en S1 : son cœur bat plus vite au repos, un signe d’alerte."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9 bpm","explication":"63 − 54 = **9 bpm** de plus au repos : une hausse nette qui s’ajoute à la forme qui chute et au sommeil dégradé."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1","i4":"c0"}},"explication":"FC, sommeil et forme sont des **signes** de surentraînement. Doubler les séances en trois semaines est la **cause** : elle a dépassé la surcharge d’environ 10 % par semaine."},{"cle":{"type":"choix","ids":["c"]},"explication":"La fiche est claire : face au surentraînement, on **lève le pied quelques jours**. Forcer aggraverait tout ; s’arrêter trois mois ferait perdre ses acquis (réversibilité)."}]$ex$::jsonb),
  ('21dd452b-bb68-53aa-990d-5157740fdf42'::uuid, 1, 1, 0, 20, 3,
   $ex${"titre":"Trois programmes à la salle","competence":"lire-tableau","situation":"À la salle du lycée, Nadia, Bastien et Camille s’entraînent côte à côte, mais ils ne font pas du tout la même chose. Voici leurs programmes du jour.","documents":[{"id":"programmes","type":"tableau","titre":"Les trois programmes","source":"Programmes écrits pour l’exercice.","colonnes":["Prénom","Séries × répétitions","Charge","Repos entre séries"],"enteteLignes":true,"lignes":[["Nadia","4 × 3","90 % du max","4 min"],["Bastien","3 × 10","75 % du max","75 s"],["Camille","3 × 20","50 % du max","30 s"]]}],"questions":[{"enonce":"Touche la **charge la plus lourde** du tableau.","aide":"Compare les pourcentages du max : le plus élevé est le plus lourd.","type":"zone","document":"programmes","multiple":false},{"enonce":"Relie chaque élève à son objectif.","aide":"Compare répétitions, charge et repos avec les trois zones du cours.","type":"association","gauche":[{"id":"g0","texte":"Nadia"},{"id":"g1","texte":"Bastien"},{"id":"g2","texte":"Camille"}],"droite":[{"id":"d0","texte":"Endurance de force"},{"id":"d1","texte":"Force maximale"},{"id":"d2","texte":"Hypertrophie"}]},{"enonce":"Pourquoi Nadia se repose-t-elle 4 minutes entre ses séries ?","aide":"À 90 % du max, que faut-il pour que la série suivante soit aussi bonne ?","type":"choix","options":[{"id":"a","texte":"Parce qu’elle manque de motivation"},{"id":"b","texte":"Pour refroidir ses muscles"},{"id":"c","texte":"Pour reconstituer ses forces et garder une charge très lourde à chaque série"},{"id":"d","texte":"Parce que ses muscles grossissent pendant le repos"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2"]},"explication":"Nadia soulève à **90 % de son max** : c’est la charge la plus lourde, et c’est aussi elle qui fait le moins de répétitions."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"**Nadia** : 3 répétitions lourdes → force maximale. **Bastien** : 10 répétitions à 75 % → hypertrophie. **Camille** : 20 répétitions légères → endurance de force."},{"cle":{"type":"choix","ids":["c"]},"explication":"Pour la force maximale, on reste sur des **charges très lourdes** : un repos de **2 à 5 minutes** est nécessaire pour retrouver sa force avant la série suivante."}]$ex$::jsonb),
  ('21dd452b-bb68-53aa-990d-5157740fdf42'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"Le carnet de Hugo et la formule d’Epley","competence":"calculer","situation":"Hugo, 17 ans, n’a jamais testé son maximum : son entraîneur le lui interdit. Il a noté ses meilleures séries du mois. Avec la formule d’Epley (charge × (1 + répétitions / 30)), il peut estimer son max sans risque.","documents":[{"id":"carnet","type":"tableau","titre":"Les meilleures séries de Hugo","source":"Chiffres imaginés pour l’exercice.","colonnes":["Exercice","Charge (kg)","Répétitions"],"enteteLignes":true,"lignes":[["Squat",70,9],["Développé couché",50,6],["Tirage",45,12]]}],"questions":[{"enonce":"Estime le **max au squat** de Hugo avec la formule d’Epley.","aide":"70 × (1 + 9 / 30) : calcule d’abord 9 / 30.","type":"nombre","unite":"kg"},{"enonce":"Estime le **max au développé couché**.","aide":"50 × (1 + 6 / 30) : 6 / 30 = 0,2.","type":"nombre","unite":"kg"},{"enonce":"Hugo veut travailler l’hypertrophie au squat à **75 % de son max**. Quelle charge doit-il charger sur la barre, arrondie au kilo ?","aide":"Reprends son max estimé au squat et multiplie par 0,75.","type":"nombre","unite":"kg"},{"enonce":"Pourquoi estimer son max plutôt que de le tester sur une seule répétition ?","aide":"Pense à ce qui peut arriver si la barre reste coincée.","type":"choix","options":[{"id":"a","texte":"Parce que la formule est plus exacte qu’un test"},{"id":"b","texte":"Pour éviter le risque d’une répétition maximale, surtout sans pareur"},{"id":"c","texte":"Parce que le max n’existe pas"},{"id":"d","texte":"Pour soulever plus lourd"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":91,"tolerance":0},"affichage":"91 kg","explication":"70 × (1 + 9/30) = 70 × 1,3 = **91 kg**. C’est une estimation : elle sert à choisir ses charges, pas à aller au bout de soi."},{"cle":{"type":"nombre","valeur":60,"tolerance":0},"affichage":"60 kg","explication":"50 × (1 + 6/30) = 50 × 1,2 = **60 kg**."},{"cle":{"type":"nombre","valeur":68,"tolerance":1},"affichage":"68 kg","explication":"91 × 0,75 ≈ 68,25, soit environ **68 kg**. À 75 %, il peut viser 6 à 12 répétitions : la zone de l’hypertrophie."},{"cle":{"type":"choix","ids":["b"]},"explication":"Un test de maximum expose aux blessures, surtout sans pareur et avant la maturité du squelette : **la formule donne un repère sûr**."}]$ex$::jsonb),
  ('21dd452b-bb68-53aa-990d-5157740fdf42'::uuid, 3, 3, 5, 50, 4,
   $ex${"titre":"La séance de Yanis, et le message qui change tout","competence":"analyser-document","situation":"Yanis, 16 ans, a fait sa séance « corps entier » seul et en parle à son coach par message. Croise le programme de la séance avec ce qu’il raconte.","documents":[{"id":"seance","type":"tableau","titre":"La séance du jour","source":"Programme écrit pour l’exercice.","colonnes":["Geste","Séries × répétitions"],"enteteLignes":true,"lignes":[["Squat","4 × 8"],["Développé couché","3 × 8"],["Tirage","3 × 10"],["Soulevé de terre léger","3 × 6"]]},{"id":"sms","type":"dialogue","modele":"sms","titre":"Le message de Yanis","participants":[{"nom":"Yanis","emoji":"👦","cote":"droite"},{"nom":"Coach","emoji":"🧑‍🏫","cote":"gauche"}],"repliques":[{"qui":"Yanis","texte":"Séance finie ! Au squat, à la dernière série, mon dos s’arrondit un peu, mais j’ai tenu."},{"qui":"Coach","texte":"Tu as continué jusqu’au bout ?"},{"qui":"Yanis","texte":"Oui, je voulais finir. Et j’ai une douleur au genou qui ne passe pas depuis hier."}]}],"questions":[{"enonce":"Touche le mot qui montre que la **technique de Yanis se dégrade** sous la charge.","aide":"Cherche ce que fait son dos au squat.","type":"zone","document":"sms","multiple":false},{"enonce":"Fatigue musculaire normale, ou signal d’alerte ? Trie ces sensations.","aide":"La fatigue se ressent dans le muscle ; la douleur d’une blessure, dans l’articulation.","type":"categories","categories":[{"id":"c0","texte":"Fatigue normale"},{"id":"c1","texte":"Signal d’alerte"}],"items":[{"id":"i0","texte":"Épaule qui pince au développé"},{"id":"i1","texte":"Dos qui s’arrondit sous la barre"},{"id":"i2","texte":"Jambes lourdes le lendemain"},{"id":"i3","texte":"Brûlure dans les cuisses en fin de série"},{"id":"i4","texte":"Souffle court après le dernier squat"},{"id":"i5","texte":"Douleur vive dans le genou"}]},{"enonce":"Combien de **répétitions** Yanis a-t-il prévu au total dans cette séance (hors gainage) ?","aide":"Pour chaque geste : séries × répétitions, puis additionne les quatre résultats.","type":"nombre"},{"enonce":"Que devait faire Yanis dès que son dos s’est arrondi ?","aide":"Relis le message : que dit-il à la dernière série ?","type":"choix","options":[{"id":"a","texte":"Poser la barre et corriger sa technique, avec un adulte compétent"},{"id":"b","texte":"Continuer en serrant les dents"},{"id":"c","texte":"Remplacer le squat par un max sur une répétition"},{"id":"d","texte":"Ajouter du poids pour finir plus vite"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11"]},"explication":"Le dos qui **s’arrondit** sous la charge est un signal d’alerte : on pose la barre au lieu de finir la série."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c0","i5":"c1"}},"explication":"La fatigue est dans le **muscle** (brûlure, souffle, jambes lourdes). Un **dos rond** ou une **douleur articulaire** vive (genou, épaule) sont des signaux d’alerte."},{"cle":{"type":"nombre","valeur":104,"tolerance":0},"affichage":"104","explication":"4 × 8 = 32 ; 3 × 8 = 24 ; 3 × 10 = 30 ; 3 × 6 = 18. Total : 32 + 24 + 30 + 18 = **104 répétitions**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Face à un dos rond ou une douleur articulaire, **on s’arrête**, on repose la barre et on fait corriger le geste. Son genou douloureux mérite un avis si la douleur persiste."}]$ex$::jsonb),
  ('f1bc637c-5cea-5b98-981c-23940f3e3230'::uuid, 1, 1, 0, 20, 3,
   $ex${"titre":"L’étiquette de la barre de céréales","competence":"analyser-document","situation":"Avant l’entraînement, Ilyès hésite devant une barre de céréales du distributeur. Il regarde l’étiquette nutritionnelle pour 100 g de produit.","documents":[{"id":"etiquette","type":"fiche","modele":"etiquette","entete":"Barre céréales-miel","sousTitre":"Valeurs pour 100 g","emoji":"🍫","lignes":[{"texte":"Énergie","valeur":"410 kcal"},{"texte":"Matières grasses","valeur":"12 g"},{"texte":"Glucides","valeur":"62 g","id":"z1"},{"texte":"Fibres","valeur":"5 g"},{"texte":"Protéines","valeur":"8 g","id":"z2"},{"texte":"Sel","valeur":"0,4 g"}],"pied":"Étiquette imaginée pour l’exercice.","teinte":"ambre"}],"questions":[{"enonce":"Touche la ligne des **protéines**.","aide":"Les protéines servent à réparer les muscles : cherche ce mot sur l’étiquette.","type":"zone","document":"etiquette","multiple":false},{"enonce":"Ilyès mange une barre de **40 g**. Combien de grammes de glucides cela représente-t-il ?","aide":"40 g, c’est 0,4 fois 100 g : multiplie les glucides pour 100 g par 0,4.","type":"nombre","unite":"g"},{"enonce":"Pourquoi une barre riche en glucides est-elle utile avant un effort intense ?","aide":"Quel nutriment est brûlé le plus vite par le muscle ?","type":"choix","options":[{"id":"a","texte":"Elle remplace l’eau"},{"id":"b","texte":"Les glucides sont le carburant de l’intensité"},{"id":"c","texte":"Elle supprime la fatigue"},{"id":"d","texte":"Les glucides réparent les muscles"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Cette barre contient **8 g de protéines pour 100 g** : peu. C’est surtout un produit riche en glucides."},{"cle":{"type":"nombre","valeur":24.8,"tolerance":0.2},"affichage":"24,8 g","explication":"62 × 0,4 = **24,8 g** de glucides : de quoi fournir du carburant pour un effort d’intensité."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les **glucides** sont le carburant de l’intensité. Les protéines servent à réparer, et rien ne remplace l’eau."}]$ex$::jsonb),
  ('f1bc637c-5cea-5b98-981c-23940f3e3230'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"Les besoins de Sara","competence":"calculer","situation":"Sara, 16 ans, pèse 55 kg et joue au basket quatre fois par semaine. Sa diététicienne lui donne des repères par kilo de poids du corps. À toi de calculer ce qu’il lui faut.","documents":[{"id":"reperes","type":"tableau","titre":"Repères pour un sportif régulier","source":"Repères du cours, présentés pour l’exercice.","colonnes":["Nutriment","Repère"],"enteteLignes":true,"lignes":[["Glucides","5 à 7 g par kilo et par jour"],["Protéines","1,2 à 2 g par kilo et par jour"],["Eau","Ne pas perdre plus de 2 % de son poids pendant l’effort"]]}],"questions":[{"enonce":"Quelle quantité **minimale** de glucides Sara doit-elle viser chaque jour ?","aide":"Multiplie 5 g par son poids en kilos.","type":"nombre","unite":"g"},{"enonce":"Et la quantité **maximale** de glucides ?","aide":"Cette fois, multiplie 7 g par 55.","type":"nombre","unite":"g"},{"enonce":"Quelle quantité **maximale** de protéines par jour correspond au repère ?","aide":"Prends le haut de la fourchette : 2 g par kilo.","type":"nombre","unite":"g"},{"enonce":"Sara ne doit pas perdre plus de 2 % de son poids en sueur. Cela fait combien de kilos d’eau, soit environ combien de litres ?","aide":"2 % de 55 kg : 55 × 0,02.","type":"nombre","unite":"L"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":275,"tolerance":0},"affichage":"275 g","explication":"5 × 55 = **275 g** de glucides par jour au minimum."},{"cle":{"type":"nombre","valeur":385,"tolerance":0},"affichage":"385 g","explication":"7 × 55 = **385 g** par jour. Sara vise donc entre 275 et 385 g de glucides."},{"cle":{"type":"nombre","valeur":110,"tolerance":0},"affichage":"110 g","explication":"2 × 55 = **110 g** de protéines par jour au maximum. Un repas normal en apporte déjà beaucoup : l’assiette suffit."},{"cle":{"type":"nombre","valeur":1.1,"tolerance":0.05},"affichage":"1,1 L","explication":"55 × 0,02 = **1,1 kg**, soit environ **1,1 litre** de sueur. Au-delà, la performance baisse : on boit avant, pendant et après, sans attendre la soif."}]$ex$::jsonb),
  ('f1bc637c-5cea-5b98-981c-23940f3e3230'::uuid, 3, 3, 5, 50, 4,
   $ex${"titre":"Le plateau de la veille de match","competence":"analyser-document","situation":"Veille de match pour Léo, 16 ans. À la cantine, il a le choix entre plusieurs plats. Son voisin lui souffle des « conseils » qu’il a lus en ligne. Croise le menu avec la fiche du vrai et du faux.","documents":[{"id":"menu","type":"fiche","modele":"menu","entete":"Cantine du lycée","sousTitre":"Mardi soir","emoji":"🍽️","lignes":[{"texte":"Pâtes au poulet","id":"z1"},{"texte":"Haricots verts","id":"z2"},{"texte":"Yaourt nature","id":"z3"},{"separateur":true},{"texte":"Canette « énergie » du distributeur","id":"z4"},{"texte":"Barre « booster » à la composition floue","id":"z5"},{"texte":"Plat du jour exotique, jamais goûté","id":"z6"}],"pied":"Menu imaginé pour l’exercice.","teinte":"vert"},{"id":"faux","type":"tableau","titre":"Idées reçues et réalité","source":"Tableau écrit pour l’exercice.","colonnes":["Idée reçue","Ce qu’on sait"],"enteteLignes":true,"lignes":[["Il faut des protéines dans les 30 minutes","Moins strict qu’on le dit : le total de la journée compte davantage"],["La créatine est un produit miracle","Pas conseillée avant 18 ans sans avis médical"],["Les boissons énergisantes donnent des ailes","Déconseillées aux adolescents par l’ANSES"],["Un complément ne peut pas poser de problème","Certains contiennent des substances dopantes non indiquées"]]}],"questions":[{"enonce":"Touche le plat qui apporte à la fois des **féculents** et des **protéines**.","aide":"Cherche le plat qui associe une source de glucides et de la viande.","type":"zone","document":"menu","multiple":false},{"enonce":"Que garde Léo pour son plateau, et que doit-il écarter la veille du match ?","aide":"Trois pièges : un produit déconseillé aux ados, un produit à la composition inconnue, une nouveauté.","type":"categories","categories":[{"id":"c0","texte":"Je le garde"},{"id":"c1","texte":"Je l’écarte"}],"items":[{"id":"i0","texte":"Haricots verts"},{"id":"i1","texte":"Yaourt nature"},{"id":"i2","texte":"Canette « énergie »"},{"id":"i3","texte":"Barre « booster » floue"},{"id":"i4","texte":"Plat exotique jamais goûté"},{"id":"i5","texte":"Pâtes au poulet"}]},{"enonce":"Relie chaque idée reçue à la bonne réponse.","aide":"Chaque ligne du deuxième tableau dit la vérité sur une idée reçue.","type":"association","gauche":[{"id":"g0","texte":"Protéines dans les 30 minutes"},{"id":"g1","texte":"Créatine miracle"},{"id":"g2","texte":"Boissons énergisantes"},{"id":"g3","texte":"Complément sans problème"}],"droite":[{"id":"d0","texte":"Pas conseillée avant 18 ans sans avis médical"},{"id":"d1","texte":"Déconseillées aux adolescents"},{"id":"d2","texte":"Peut contenir des substances dopantes"},{"id":"d3","texte":"Le total de la journée compte davantage"}]},{"enonce":"Pourquoi la barre « booster » à la composition floue peut-elle poser problème à un athlète ?","aide":"Pense à ce que l’athlète est toujours responsable d’avaler.","type":"choix","options":[{"id":"a","texte":"Elle peut contenir une substance dopante non indiquée : un contrôle positif « involontaire » reste positif"},{"id":"b","texte":"Elle est interdite à la vente"},{"id":"c","texte":"Elle remplace les protéines de l’assiette"},{"id":"d","texte":"Elle contient forcément trop de sel"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Les **pâtes au poulet** apportent des féculents (carburant) et des protéines (réparation) : c’est le plat idéal la veille d’un match."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c1","i5":"c0"}},"explication":"On écarte la **canette** (déconseillée aux adolescents), la **barre floue** (risque de substances dopantes) et le **plat jamais goûté** (jamais de nouveauté le jour J)."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Les quatre idées reçues sont corrigées par le tableau : fenêtre anabolique moins stricte, créatine déconseillée avant 18 ans, boissons énergisantes déconseillées par l’ANSES, compléments parfois dopants."},{"cle":{"type":"choix","ids":["a"]},"explication":"Certains compléments contiennent des **substances interdites non étiquetées**. Dire « je ne savais pas » ne protège pas : l’athlète est responsable de ce qu’il avale."}]$ex$::jsonb),
  ('e270f3b1-967c-5a19-9e3c-05e83ee12861'::uuid, 1, 1, 0, 20, 3,
   $ex${"titre":"Du plus léger au plus grave","competence":"lire-tableau","situation":"Le kiné du club affiche dans le vestiaire un tableau des lésions musculaires, pour que les joueurs comprennent pourquoi un « petit claquage » n’est pas un petit bobo.","documents":[{"id":"lesions","type":"tableau","titre":"Les lésions musculaires","source":"Délais indicatifs : seul un avis médical précise la durée du repos.","colonnes":["Lésion","Ce qui se passe","Délai indicatif"],"enteteLignes":true,"lignes":[["Contracture","Muscle durci et douloureux","Environ 1 semaine"],["Élongation","Fibres étirées","Quelques semaines"],["Claquage","Rupture de quelques fibres","Plusieurs semaines"],["Déchirure","Rupture plus étendue","6 semaines et plus"]]}],"questions":[{"enonce":"Touche le **délai indicatif d’un claquage**.","aide":"Ligne « Claquage », dernière colonne.","type":"zone","document":"lesions","multiple":false},{"enonce":"Range ces lésions de la **moins grave à la plus grave**.","aide":"Le délai de guérison indique la gravité : du plus court au plus long.","type":"ordre","items":[{"id":"a","texte":"Déchirure"},{"id":"b","texte":"Élongation"},{"id":"c","texte":"Contracture"},{"id":"d","texte":"Claquage"}]},{"enonce":"Au minimum, combien de semaines de repos faut-il compter pour une **déchirure** ?","aide":"Lis le délai de la dernière ligne du tableau.","type":"nombre","unite":"semaines"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c2"]},"explication":"Un claquage demande **plusieurs semaines** : ce n’est pas une petite douleur qu’on soigne en deux jours."},{"cle":{"type":"ordre","ids":["c","b","d","a"]},"explication":"Contracture (≈ 1 semaine), élongation (quelques semaines), claquage (plusieurs semaines), **déchirure** (6 semaines et plus)."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6 semaines","explication":"Le tableau indique **6 semaines et plus**. Seul un avis médical précise la durée exacte."}]$ex$::jsonb),
  ('e270f3b1-967c-5a19-9e3c-05e83ee12861'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"Trois scènes de vestiaire","competence":"analyser-texte","situation":"Samedi, match de handball du lycée. À la mi-temps, trois scènes se jouent dans les vestiaires. À toi de reconnaître chaque blessure et de choisir la bonne conduite.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"À la mi-temps","source":"Texte écrit pour l’exercice.","blocs":["Scène 1. Eliott a atterri sur le pied d’un adversaire. Sa cheville a doublé de volume et il n’arrive plus à poser le pied par terre.","Scène 2. Maëlys court depuis la rentrée. Depuis trois semaines, son tendon d’Achille la tire chaque matin. Elle a doublé ses kilomètres en un mois.","Scène 3. Karim a pris un coude dans la tête. Il répète trois fois la même question, il est confus, il a une forte nausée et il voit double. Il jure que « ça va » et veut retourner jouer."]}],"questions":[{"enonce":"Relie chaque joueur à sa blessure.","aide":"Ligament, tendon, cerveau : cherche l’organe touché dans chaque scène.","type":"association","gauche":[{"id":"g0","texte":"Eliott"},{"id":"g1","texte":"Maëlys"},{"id":"g2","texte":"Karim"}],"droite":[{"id":"d0","texte":"Tendinopathie de surcharge"},{"id":"d1","texte":"Commotion cérébrale"},{"id":"d2","texte":"Entorse de la cheville"}]},{"enonce":"Touche les **trois mots** qui trahissent une commotion chez Karim.","aide":"Cherche les signes décrits dans la scène 3 : confusion, nausée, trouble de la vue.","type":"zone","document":"recit","multiple":true},{"enonce":"Que faut-il faire pour Karim ?","aide":"Retiens la phrase du cours : « Au moindre doute, … ».","type":"choix","options":[{"id":"a","texte":"Le sortir : au moindre doute, il ne rejoue pas, repos puis reprise progressive par paliers"},{"id":"b","texte":"Le remettre en jeu après dix minutes de pause"},{"id":"c","texte":"Lui donner une boisson énergisante"},{"id":"d","texte":"Le laisser jouer s’il dit que ça va"}],"multiple":false},{"enonce":"Quelle erreur de Maëlys explique son tendon douloureux ?","aide":"Relis ce que Maëlys a fait de ses kilomètres en un mois.","type":"choix","options":[{"id":"a","texte":"Elle s’est entraînée sans chaussures"},{"id":"b","texte":"Elle a trop dormi"},{"id":"c","texte":"Elle n’a pas bu assez de lait"},{"id":"d","texte":"Elle a augmenté sa charge trop vite : le tendon n’a pas eu le temps de s’adapter"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Eliott : cheville gonflée après une torsion → **entorse** (ligament). Maëlys : trop de kilomètres trop vite → **tendinopathie de surcharge**. Karim : choc à la tête avec signes → **commotion**."},{"cle":{"type":"zone","ids":["m73","m78","m82"]},"explication":"**Confus**, **nausée** et **double** (vision double) sont des signes de commotion. Karim ne finira pas le match, même s’il dit aller bien."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Au moindre doute, on sort.** Un second choc sur un cerveau fragilisé peut être grave, et le retour prend plusieurs semaines pour un mineur."},{"cle":{"type":"choix","ids":["d"]},"explication":"La plupart des « tendinites » sont des surcharges : **trop d’effort, trop vite**. La solution est d’adapter la charge et de renforcer progressivement."}]$ex$::jsonb),
  ('e270f3b1-967c-5a19-9e3c-05e83ee12861'::uuid, 3, 3, 5, 50, 4,
   $ex${"titre":"Le tendon de Mina","competence":"raisonner","situation":"Mina, 16 ans, prépare un 10 km. Depuis la semaine 5, son tendon d’Achille la fait souffrir. Elle consulte un kinésithérapeute, qui lui répond par message. Croise son carnet avec le message.","documents":[{"id":"volume","type":"graphique","forme":"barres","titre":"Kilomètres courus par semaine","source":"Chiffres imaginés pour l’exercice.","categories":["S1","S2","S3","S4","S5","S6"],"series":[{"nom":"Mina","valeurs":[20,22,26,32,40,50],"teinte":"violet"}],"axeY":{"titre":"Volume","unite":"km","min":0,"max":60,"pas":10},"axeX":{"titre":"Semaine"},"valeurs":false},{"id":"message","type":"texte","genre":"lettre","titre":"Le message du kinésithérapeute","source":"Message écrit pour l’exercice.","blocs":["Bonjour Mina, je ne trouve ni rupture ni lésion grave : c’est une tendinopathie de surcharge. Ton tendon n’a pas eu le temps de s’adapter à ta progression.","On ne s’arrête pas complètement : on ramène la charge à un niveau supportable, puis on la remonte progressivement, avec du renforcement des mollets.","Reviens me voir si la douleur te réveille la nuit ou si elle persiste."]}],"questions":[{"enonce":"Touche la **première semaine** où la hausse du volume dépasse nettement 10 % (de 20 à 22 km, c’était exactement 10 %).","aide":"S2 : +2 km sur 20 km = 10 %. Cherche la semaine suivante où la hausse est plus forte.","type":"zone","document":"volume","multiple":false},{"enonce":"De quel pourcentage Mina a-t-elle augmenté son volume entre S4 et S5 ?","aide":"De 32 à 40 km : la hausse est de 8 km. Rapporte-la à 32.","type":"nombre","unite":"%"},{"enonce":"Quel lien le kiné fait-il entre le graphique et la douleur de Mina ?","aide":"Compare la courbe de ses kilomètres avec la phrase « trop, trop vite ».","type":"choix","options":[{"id":"a","texte":"Elle n’a pas assez couru"},{"id":"b","texte":"Son tendon a reçu trop d’effort, trop vite : c’est une tendinopathie de surcharge"},{"id":"c","texte":"Son tendon s’est rompu net"},{"id":"d","texte":"Elle s’est fait une entorse à la cheville"}],"multiple":false},{"enonce":"Quelle conduite le kiné recommande-t-il ?","aide":"Relis le deuxième paragraphe du message.","type":"choix","options":[{"id":"a","texte":"Courir malgré la douleur, elle passera"},{"id":"b","texte":"Arrêter tout mouvement pendant trois mois"},{"id":"c","texte":"Doubler les séances pour « muscler » le tendon"},{"id":"d","texte":"Ramener la charge à un niveau supportable, puis la remonter progressivement en renforçant les mollets"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k2"]},"explication":"De S2 à S3, Mina passe de 22 à 26 km : **+18 %**. C’est le début de l’emballement, bien au-delà des 10 % par semaine conseillés."},{"cle":{"type":"nombre","valeur":25,"tolerance":0},"affichage":"25 %","explication":"8 / 32 = 0,25, soit **+25 %** en une semaine : plus de deux fois et demie la hausse recommandée."},{"cle":{"type":"choix","ids":["b"]},"explication":"La courbe montre une progression **bien trop rapide** : ce que le kiné appelle une tendinopathie de surcharge. Pas de rupture, donc pas d’arrêt total."},{"cle":{"type":"choix","ids":["d"]},"explication":"On **adapte la charge** puis on la remonte peu à peu, avec du **renforcement** : l’arrêt total n’est pas la solution, et forcer aggraverait la surcharge."}]$ex$::jsonb),
  ('78dffff4-cbfc-5911-95cb-6520d0db2c2d'::uuid, 1, 1, 0, 20, 3,
   $ex${"titre":"Quand le sport s’écrit","competence":"se-reperer-temps","situation":"À la fin du XIXe siècle, des clubs naissent des deux côtés de la Manche. La frise place quelques repères du sport moderne, de l’Angleterre à la France.","documents":[{"id":"frise","type":"frise","titre":"Les débuts du sport moderne","debut":1860,"fin":1885,"pas":5,"evenements":[{"id":"z1","date":1863,"nom":"Football Association"},{"id":"z2","date":1871,"nom":"Rugby Football Union"},{"id":"z3","date":1874,"nom":"Brevet du tennis"},{"id":"z4","date":1882,"nom":"Racing Club"}]}],"questions":[{"enonce":"Touche la **création de la Football Association**.","aide":"Cherche l’événement le plus à gauche de la frise.","type":"zone","document":"frise","multiple":false},{"enonce":"Range ces événements du plus ancien au plus récent.","aide":"Lis les dates sur la frise, de gauche à droite.","type":"ordre","items":[{"id":"a","texte":"Création de la Football Association (1863)"},{"id":"b","texte":"Brevet du lawn-tennis (1874)"},{"id":"c","texte":"Création du Racing Club de France (1882)"},{"id":"d","texte":"Création de la Rugby Football Union (1871)"}]},{"enonce":"Combien d’années séparent la création de la Football Association de celle de la Rugby Football Union ?","aide":"Soustrais les deux dates lues sur la frise.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
