  ('78dffff4-cbfc-5911-95cb-6520d0db2c2d'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"Gymnastique contre sport anglais","competence":"analyser-document","situation":"Vers 1880, deux façons de faire bouger la jeunesse française s’opposent : la gymnastique, venue du modèle allemand, et le sport apporté par des Anglais installés en France. Un élève a résumé leurs différences.","documents":[{"id":"comparatif","type":"tableau","titre":"Deux manières de s’entraîner","source":"Tableau écrit pour l’exercice.","colonnes":["","Gymnastique (modèle allemand)","Sport anglais"],"enteteLignes":true,"lignes":[["But","Former des corps forts pour la patrie","Jouer, se mesurer, gagner"],["Où","Écoles et bataillons scolaires","Clubs"],["Façon de faire","Exercices imposés, discipline","Règles de jeu codifiées, plus libre et ludique"]]}],"questions":[{"enonce":"Gymnastique ou sport anglais ? Trie ces éléments.","aide":"Reprends les colonnes du tableau : chaque élément s’y trouve, ou presque.","type":"categories","categories":[{"id":"c0","texte":"Gymnastique"},{"id":"c1","texte":"Sport anglais"}],"items":[{"id":"i0","texte":"Match avec règles écrites"},{"id":"i1","texte":"Former des corps forts pour la patrie"},{"id":"i2","texte":"Bataillons scolaires"},{"id":"i3","texte":"Exercices imposés"},{"id":"i4","texte":"Se mesurer pour gagner"},{"id":"i5","texte":"Clubs comme le Havre Athletic Club"}]},{"enonce":"Touche la case qui dit **où se pratique le sport anglais**.","aide":"Ligne « Où », colonne « Sport anglais ».","type":"zone","document":"comparatif","multiple":false},{"enonce":"Le Havre Athletic Club est fondé en 1872 et le Stade français en 1883. Combien d’années séparent ces deux fondations ?","aide":"Soustrais 1872 à 1883.","type":"nombre","unite":"ans"},{"enonce":"Qui a apporté les premiers jeux anglais en France ?","aide":"Le Havre Athletic Club, c’est un nom bien français, mais qui l’a fondé ?","type":"choix","options":[{"id":"a","texte":"Le ministère des Sports"},{"id":"b","texte":"Des Anglais installés en France"},{"id":"c","texte":"Les congés payés de 1936"},{"id":"d","texte":"Des militaires allemands"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c0","i4":"c1","i5":"c1"}},"explication":"La gymnastique va avec **bataillons scolaires, exercices imposés, corps forts pour la patrie**. Le sport anglais va avec **clubs, matchs à règles écrites, compétition**."},{"cle":{"type":"zone","ids":["r1c2"]},"explication":"Le sport anglais se pratique en **clubs**, comme le Havre Athletic Club fondé en 1872, tandis que la gymnastique se fait à l’école."},{"cle":{"type":"nombre","valeur":11,"tolerance":0},"affichage":"11 ans","explication":"1883 − 1872 = **11 ans** : en une décennie, les clubs fondés par des Anglais et leurs imitateurs se multiplient."},{"cle":{"type":"choix","ids":["b"]},"explication":"Ce sont des **Anglais installés en France** qui apportent leurs jeux et fondent les premiers clubs, d’abord réservés à une élite."}]$ex$::jsonb),
  ('78dffff4-cbfc-5911-95cb-6520d0db2c2d'::uuid, 3, 3, 5, 50, 4,
   $ex${"titre":"Le dossier de Nina","competence":"raisonner","situation":"Nina prépare un exposé sur « Comment le sport est devenu l’affaire de tous ». Elle a posé quatre dates sur une frise et rédigé trois idées. À toi de les relier.","documents":[{"id":"frise","type":"frise","titre":"Quatre dates de Nina","debut":1860,"fin":1940,"pas":20,"evenements":[{"id":"z1","date":1863,"nom":"Football Association"},{"id":"z2","date":1872,"nom":"Le Havre AC"},{"id":"z3","date":1901,"nom":"Loi sur les associations"},{"id":"z4","date":1936,"nom":"Front populaire"}]},{"id":"dossier","type":"texte","genre":"article","titre":"Les trois idées de Nina","source":"Texte écrit pour l’exercice.","blocs":["Première idée : le sport moderne vient d’Angleterre, où des élèves de public schools ont écrit des règles communes pour que des équipes de lieux différents puissent s’affronter.","Deuxième idée : en France, on a longtemps fait de la gymnastique. Puis une loi a permis à n’importe qui de créer une association, et les clubs se sont multipliés partout.","Troisième idée : en 1936, avec les congés payés, le sport et les loisirs sont devenus accessibles au plus grand nombre."]}],"questions":[{"enonce":"Touche sur la frise l’événement qui correspond à la **deuxième idée** de Nina (la loi qui permet de créer une association).","aide":"Cherche la date de la loi sur les associations.","type":"zone","document":"frise","multiple":false},{"enonce":"Touche le mot de la troisième idée qui désigne les vacances **payées**.","aide":"Cherche le mot juste avant « payés ».","type":"zone","document":"dossier","multiple":false},{"enonce":"Combien d’années séparent la fondation du Havre AC de la loi sur les associations ?","aide":"Soustrais 1872 à 1901.","type":"nombre","unite":"ans"},{"enonce":"Relie chaque date à ce qu’elle change pour le sport.","aide":"Chaque idée du dossier correspond à l’une des trois dates.","type":"association","gauche":[{"id":"g0","texte":"1863"},{"id":"g1","texte":"1901"},{"id":"g2","texte":"1936"}],"droite":[{"id":"d0","texte":"Congés payés et sport pour tous"},{"id":"d1","texte":"Des règles écrites et communes pour le football"},{"id":"d2","texte":"N’importe qui peut créer un club"}]}]}$ex$::jsonb,
