  ('e37c9cb1-203b-566b-b39b-917ad4cb95c6'::uuid, 3, 3, 5, 50, 4,
   $ex${"titre":"Exclus, boycottés, suspendus","competence":"raisonner","situation":"Élodie prépare un débat intitulé « Le sport est-il neutre ? ». Elle a posé une frise et noté trois affirmations. À toi de les confronter.","documents":[{"id":"frise","type":"frise","titre":"Le sport et la politique, 1960-2030","debut":1960,"fin":2030,"pas":10,"periodes":[{"id":"z1","debut":1964,"fin":1992,"nom":"Afrique du Sud exclue","teinte":"corail"}],"evenements":[{"id":"z2","date":1968,"nom":"Mexico"},{"id":"z3","date":1972,"nom":"Munich"},{"id":"z4","date":1980,"nom":"Moscou"},{"id":"z5","date":1984,"nom":"Los Angeles"},{"id":"z6","date":2022,"nom":"Russie suspendue"}]},{"id":"notes","type":"texte","genre":"article","titre":"Les notes d’Élodie","source":"Texte écrit pour l’exercice.","blocs":["A. Les Jeux de 1980 et de 1984 ont été boycottés : la guerre froide s’est invitée dans le stade.","B. Pendant près de trente ans, l’Afrique du Sud, pays de l’apartheid, n’a pas pu participer aux Jeux.","C. Depuis 2022, la Russie est suspendue ; à Paris en 2024, ses athlètes ont concouru sous bannière « neutre »."]}],"questions":[{"enonce":"Touche les **quatre éditions des Jeux** de la frise qui se sont tenues pendant l’exclusion de l’Afrique du Sud.","aide":"L’exclusion dure de 1964 à 1992 : garde les événements situés dans cette période.","type":"zone","document":"frise","multiple":true},{"enonce":"Combien d’années dure l’exclusion de l’Afrique du Sud des Jeux ?","aide":"La période va de 1964 à 1992.","type":"nombre","unite":"ans"},{"enonce":"Boycott volontaire ou exclusion/suspension imposée ? Trie ces situations.","aide":"Un boycott est décidé par les pays qui refusent de venir ; une exclusion est décidée contre un pays.","type":"categories","categories":[{"id":"c0","texte":"Boycott"},{"id":"c1","texte":"Exclusion ou suspension"}],"items":[{"id":"i0","texte":"Afrique du Sud, 1964-1992"},{"id":"i1","texte":"Russie, depuis 2022"},{"id":"i2","texte":"Los Angeles 1984"},{"id":"i3","texte":"Moscou 1980"}]},{"enonce":"Quelle conclusion Élodie peut-elle tirer de ses trois notes pour son débat ?","aide":"Boycotts, exclusions, suspensions : qu’est-ce qui les motive ?","type":"choix","options":[{"id":"a","texte":"Seul le football est concerné"},{"id":"b","texte":"Un grand événement sportif est aussi un message politique : le sport n’est jamais neutre"},{"id":"c","texte":"Les boycotts n’ont jamais eu lieu"},{"id":"d","texte":"Le sport est toujours à l’écart de la politique"}],"multiple":false}]}$ex$::jsonb,
