) AS v (chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu, cles);

INSERT INTO public.exercices (id, chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu)
SELECT s.id, s.chapter_id, s.position, s.etoiles, s.gemmes, s.xp, s.nb_questions, s.contenu
FROM exercices_seed s
JOIN public.chapters c ON c.id = s.chapter_id
ON CONFLICT (id) DO UPDATE
  SET etoiles      = EXCLUDED.etoiles,
      nb_questions = EXCLUDED.nb_questions,
      contenu      = EXCLUDED.contenu,
      updated_at   = now();

INSERT INTO public.exercices_cles (exercice_id, cles)
SELECT s.id, s.cles
FROM exercices_seed s
JOIN public.exercices e ON e.id = s.id
ON CONFLICT (exercice_id) DO UPDATE SET cles = EXCLUDED.cles;

-- Contrôle : combien d'exercices de ce fichier sont en base, et combien sautés.
DO $$
DECLARE
  v_attendus INTEGER;
  v_poses    INTEGER;
BEGIN
  SELECT count(*) INTO v_attendus FROM exercices_seed;
  SELECT count(*) INTO v_poses FROM public.exercices e JOIN exercices_seed s ON s.id = e.id;
  RAISE NOTICE 'Cahier 1re : % exercices posés sur % (les autres n''ont pas leur chapitre en base).', v_poses, v_attendus;
  DROP TABLE IF EXISTS pg_temp.exercices_seed;
END $$;


-- =============================================================================
-- 574 — LE CATALOGUE DES CONTRÔLES BLANCS : 1re (sport)
--
-- 30 sujets écrits d'avance et relus : pour chaque fiche, un sujet
-- Facile, un Moyen, un Difficile, chacun avec son barème sur 20 et son corrigé
-- type (`contenu.corrige`, jamais envoyé à l'élève avant sa copie). L'IA ne fait
-- plus que les corriger ; elle ne rédige que « Un autre sujet ».
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main. Source : contenu/controles/.
--    Regénérer : node node_modules/jiti/lib/jiti-cli.mjs scripts/controles-sql.ts --num 574 --niveau 1re --matieres sport
--
--   sport.culture                30 sujets · 10 fiches
--
-- L'identifiant d'un sujet est dérivé de (fiche, niveau) : rejouer la migration
-- met le sujet à jour au lieu de le dupliquer. Une fiche absente est sautée.
--
-- PRÉREQUIS : 360 puis 364. Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

INSERT INTO public.chapter_exercices
  (id, chapter_id, style, contenu, difficulte, origine, created_by)
SELECT
  md5('exercice-catalogue:' || v.chapter_id::text || ':' || v.difficulte::text)::uuid,
  v.chapter_id,
  v.style,
  v.contenu,
  v.difficulte,
  'catalogue',
  NULL
FROM (VALUES
  ('b6124e13-4abd-5a43-8fbb-7e9992ff56b7'::uuid, 1, 'redaction', $exo${"titre":"Les trois filières","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Quelle est la seule molécule que le muscle sait dépenser ? Pourquoi doit-il sans cesse la refabriquer ?\n2. Nomme les **trois filières énergétiques** et donne pour chacune la durée où elle domine et un exemple d’épreuve.\n3. Le lactate est-il un poison responsable des courbatures ? Justifie.","bareme":[{"critere":"L’ATP nommée, avec son stock minuscule qui oblige à la refabriquer","points":5},{"critere":"Les trois filières avec leur durée (0-10 s, 10 s-2 min, au-delà de 2 min) et un exemple chacune","points":8},{"critere":"Lactate : carburant recyclé, pas un poison ; courbatures dues aux micro-lésions","points":7}],"dureeMin":8,"corrige":"1. Le muscle ne dépense que de l’**ATP**. Son stock est **minuscule** (quelques secondes d’effort) : tout l’effort consiste donc à **refabriquer de l’ATP** aussi vite qu’on la consomme.\n\n2. **Anaérobie alactique** : de 0 à environ **10 s**, grâce à la phosphocréatine (sprint, saut, lancer). **Anaérobie lactique** : d’environ **10 s à 2 min**, par la glycolyse sans oxygène (400 m, 100 m nage). **Aérobie** : au-delà de **2 min**, avec de l’oxygène, glucides puis lipides (10 km, marathon).\n\n3. Non. Le lactate est un déchet de la glycolyse, mais surtout un **carburant recyclé** : le cœur et les muscles voisins le réutilisent et le foie le retransforme en glucose. Les **courbatures** viennent de **micro-lésions** dans les fibres, pas du lactate."}$exo$::jsonb),
  ('b6124e13-4abd-5a43-8fbb-7e9992ff56b7'::uuid, 2, 'redaction', $exo${"titre":"Trois épreuves, trois corps","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Trois athlètes d’un même club : Inès court le **100 m**, Yanis le **400 m**, Sofia le **10 000 m**.\n\n1. Pour chacun, indique la **filière dominante** et son carburant.\n2. À la fin de son 400 m, Yanis dit : *« Mes jambes brûlent, c’est le lactate qui m’empoisonne. »* Corrige cette affirmation.\n3. Propose, pour **chaque** athlète, un entraînement adapté à sa filière.\n4. Le professeur dit que les trois filières « tournent toujours ensemble ». Explique cette phrase avec l’exemple de Sofia dans son sprint final.","bareme":[{"critere":"Filière dominante et carburant corrects pour les trois athlètes","points":5},{"critere":"Affirmation sur le lactate corrigée : carburant recyclé ; ensemble de changements qui empêche le muscle de continuer","points":5},{"critere":"Un entraînement adapté par filière (récupération complète, séries de 30 s à 2 min, volume)","points":6},{"critere":"Chevauchement des filières expliqué : l’aérobie domine, mais le sprint final fait remonter les deux autres","points":4}],"dureeMin":12,"corrige":"1. **Inès (100 m)** : filière **anaérobie alactique**, carburant = la **phosphocréatine** déjà stockée dans le muscle. **Yanis (400 m)** : filière **anaérobie lactique**, carburant = le **glucose** (glycolyse, sans oxygène). **Sofia (10 000 m)** : filière **aérobie**, avec **oxygène**, glucides puis lipides.\n\n2. C’est faux : le lactate n’est pas un poison, c’est un **carburant recyclé** (le cœur et les muscles le réutilisent, le foie le retransforme en glucose). Si les jambes brûlent, c’est tout un **ensemble de changements dans le muscle** qui l’empêche de continuer au même rythme. Les courbatures, elles, viennent de micro-lésions.\n\n3. Inès : des **efforts très courts et maximaux** avec une **récupération complète** entre chaque. Yanis : des **séries de 30 secondes à 2 minutes** à forte intensité, avec une récupération incomplète. Sofia : du **volume**, de longues séances à allure modérée, régulières.\n\n4. Les filières ne s’allument pas comme des interrupteurs : à chaque instant les **trois tournent**, l’une **domine**. Pendant le 10 000 m, l’**aérobie** fournit presque tout, mais le **sprint final** fait remonter les deux filières anaérobies."}$exo$::jsonb),
  ('b6124e13-4abd-5a43-8fbb-7e9992ff56b7'::uuid, 3, 'redaction', $exo${"titre":"Puissance et durée","consigne":"Rédige une réponse argumentée, avec des exemples précis tirés du cours.","enonce":"Un camarade affirme : *« Pour être le meilleur en sport, il suffit d’avoir un gros moteur aérobie : il fournit de l’énergie sans jamais s’épuiser, donc c’est la meilleure filière. Les autres ne servent à rien. »*\n\nRédige une réponse argumentée qui : **(1)** explique pourquoi cette affirmation est fausse, en comparant les filières (puissance, durée, carburant) ; **(2)** utilise au moins deux épreuves d’athlétisme comme exemples ; **(3)** montre, avec un sport collectif, qu’un sportif a besoin des trois filières et dit comment les entraîner.","bareme":[{"critere":"Comparaison puissance/durée : l’aérobie est inépuisable mais moins puissante ; les filières anaérobies sont immédiates mais s’épuisent vite","points":6},{"critere":"Deux épreuves bien associées à leur filière (100 m et 10 000 m, par exemple)","points":4},{"critere":"Sport collectif : démarrages explosifs, enchaînements intenses, moteur aérobie qui récupère vite","points":5},{"critere":"Entraînement de chaque filière et qualité de la rédaction","points":5}],"dureeMin":15,"corrige":"**Réponse attendue.** L’affirmation est fausse, car **aucune filière n’est « la meilleure »** : chacune répond à une durée d’effort. La filière **aérobie** est **quasi inépuisable** (glucides puis lipides, avec de l’oxygène), mais elle démarre lentement et elle est **moins puissante**. À l’inverse, les filières **anaérobies** sont **immédiates et très puissantes**, mais elles s’épuisent vite : l’**alactique** (phosphocréatine) dure de 0 à environ **10 s**, la **lactique** (glycolyse, sans oxygène) d’environ **10 s à 2 min**. Autrement dit, **puissance et durée ne vont jamais ensemble** : plus l’effort est intense, plus il est court.\n\nLes épreuves le montrent : un sprinteur de **100 m** vit sur la filière **alactique** et n’a besoin que de dix secondes de carburant ; un fondeur de **10 000 m** vit sur la filière **aérobie** pendant plus de vingt-cinq minutes. Un moteur aérobie énorme ne fera jamais gagner un 100 m.\n\nDans un **sport collectif** comme le football ou le basket, un joueur a besoin des **trois** : des **démarrages explosifs** (alactique), des **enchaînements intenses** (lactique) et un **moteur aérobie** qui permet de récupérer vite entre les actions. Les trois filières **se chevauchent en permanence**, l’une domine selon l’intensité et la durée.\n\nOn les entraîne séparément : des **efforts très courts et maximaux avec récupération complète** pour l’alactique, des **séries de 30 s à 2 min** pour la lactique, du **volume à allure modérée** pour l’aérobie. **Conclusion** : un bon programme travaille les trois filières, dans les proportions que demande le sport pratiqué."}$exo$::jsonb),
  ('18025266-7610-5538-8081-e77ac4ab711c'::uuid, 1, 'redaction', $exo${"titre":"Les réglages de la charge","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Nomme les **quatre réglages** de la charge d’entraînement et donne un exemple pour chacun.\n2. Que signifie le sigle **FITT** ?\n3. Qu’est-ce que la **surcharge progressive** ? Donne la valeur repère par semaine.\n4. Que se passe-t-il après 2 à 3 semaines d’arrêt ? Comment s’appelle ce principe ?","bareme":[{"critere":"Quatre réglages nommés (volume, intensité, densité, fréquence) avec un exemple chacun","points":7},{"critere":"FITT : fréquence, intensité, temps, type d’exercice","points":4},{"critere":"Surcharge progressive définie, avec environ 10 % de plus par semaine","points":5},{"critere":"Réversibilité : les acquis redescendent après 2 à 3 semaines d’arrêt","points":4}],"dureeMin":8,"corrige":"1. **Volume** : la quantité de travail (durée, distance, répétitions). **Intensité** : la difficulté de l’effort (% de VMA, de la charge max, de la fréquence cardiaque max). **Densité** : le rapport entre effort et repos (30 s d’effort pour 30 s de repos). **Fréquence** : le nombre de séances (trois par semaine).\n\n2. **FITT** : **F**réquence, **I**ntensité, **T**emps, **T**ype d’exercice.\n\n3. La **surcharge progressive** consiste à demander **un peu plus qu’avant** pour progresser : environ **10 % de plus par semaine**, pas davantage.\n\n4. Après **2 à 3 semaines d’arrêt**, les acquis **redescendent** : c’est la **réversibilité**."}$exo$::jsonb),
  ('18025266-7610-5538-8081-e77ac4ab711c'::uuid, 2, 'redaction', $exo${"titre":"Le programme de Malik","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Malik, 16 ans, débutant, veut courir un 10 km. Il s’est fixé ceci pour sa première semaine : *« Six séances de 10 km à fond, tous les jours sauf le dimanche. La semaine suivante, je double les distances et je passe en plus à des fractionnés tous les jours. »*\n\n1. Relève **trois erreurs** dans ce programme en citant le principe du cours que chacune enfreint.\n2. Propose une **semaine type à trois séances** adaptée à un coureur débutant, en précisant l’intérêt de chaque séance.\n3. Après trois semaines, Malik est épuisé, dort mal et son cœur bat plus vite au repos. Que lui arrive-t-il et que doit-il faire ?","bareme":[{"critere":"Trois erreurs relevées avec le principe enfreint (surcharge de 10 %, récupération, un seul bouton à la fois, individualisation)","points":7},{"critere":"Semaine type cohérente : endurance fondamentale, fractionné, renforcement, avec l’intérêt de chacune","points":7},{"critere":"Surentraînement identifié, avec ses signes, et conduite à tenir : lever le pied quelques jours","points":6}],"dureeMin":12,"corrige":"1. **Six séances à fond** : on ne respecte pas la **récupération** (le progrès se fait au repos) ni l’**individualisation** (un débutant n’a pas le programme d’un coureur confirmé). **Doubler les distances** : la surcharge doit rester d’environ **10 % par semaine**. **Tout changer en même temps** (distance, fractionné, fréquence) : on ne tourne qu’**un bouton à la fois**, sinon on ne sait plus ce qui marche et le corps encaisse mal.\n\n2. **Lundi** : endurance fondamentale, allure facile, pour construire le moteur aérobie. **Mercredi** : fractionné (répétitions rapides entrecoupées de récupération) pour gagner en vitesse. **Samedi** : renforcement (gainage, squats au poids du corps) pour solidifier le corps et éviter les blessures. Les jours entre les séances ne sont pas perdus : ils rendent la progression possible.\n\n3. Malik présente des signes de **surentraînement** : fatigue permanente, mauvais sommeil, cœur plus rapide au repos. La réponse n’est pas de forcer, mais de **lever le pied quelques jours**, puis de reprendre avec un programme plus raisonnable. Un **carnet d’entraînement** (ressenti sur dix, fréquence cardiaque) lui aurait permis de s’en apercevoir plus tôt."}$exo$::jsonb),
  ('18025266-7610-5538-8081-e77ac4ab711c'::uuid, 3, 'redaction', $exo${"titre":"La régularité contre l’exploit","consigne":"Rédige une réponse argumentée, avec des exemples précis tirés du cours.","enonce":"Une camarade affirme : *« Pour progresser vite en sport, il faut s’entraîner le plus dur possible, le plus souvent possible, et ne jamais prendre de repos : le repos, c’est de la paresse. »*\n\nRédige une réponse argumentée qui : **(1)** explique pourquoi le repos fait partie de l’entraînement ; **(2)** utilise au moins trois principes d’un bon programme pour réfuter l’affirmation ; **(3)** décrit comment tu construirais SON programme sur un mois (réglages, progression, suivi).","bareme":[{"critere":"Le progrès se fait au repos : récupération expliquée, signes du surentraînement","points":5},{"critere":"Au moins trois principes mobilisés à bon escient (surcharge de 10 %, réversibilité, variété, individualisation, spécificité)","points":6},{"critere":"Programme d’un mois cohérent : un bouton à la fois, progression, carnet d’entraînement","points":5},{"critere":"Argumentation structurée et conclusion","points":4}],"dureeMin":15,"corrige":"**Réponse attendue.** L’affirmation est fausse : **le progrès se fait au repos, pas pendant la séance**. L’effort crée une fatigue et une petite agression du corps ; c’est pendant la **récupération** que le corps se reconstruit un peu plus solide. Sans repos, on s’épuise : fatigue permanente, performances qui stagnent ou baissent, mauvais sommeil, irritabilité, cœur plus rapide au repos sont les signes du **surentraînement**. La réponse est alors de **lever le pied**.\n\nPlusieurs principes réfutent l’idée. La **surcharge progressive** demande **un peu plus qu’avant**, environ **10 % par semaine**, et non le maximum d’emblée. L’**individualisation** rappelle que le programme d’un autre n’est pas le mien (âge, niveau, objectif, sommeil). La **variété** évite l’ennui et les blessures de répétition. Et la **réversibilité** nuance l’autre extrême : après **2 à 3 semaines d’arrêt**, les acquis redescendent, donc la **régularité** compte plus que l’exploit.\n\nPour mon mois, je fixerais un objectif, puis je réglerais les **quatre boutons** (volume, intensité, densité, fréquence) **un à la fois**, selon le principe **FITT**. Je commencerais par **trois séances par semaine** (par exemple endurance fondamentale, fractionné, renforcement), avec des jours de repos entre elles, et j’augmenterais la charge d’environ **10 % par semaine**. Je tiendrais un **carnet d’entraînement** (ce que j’ai fait, fréquence cardiaque, ressenti sur dix, forme) pour voir ce qui marche et être alerté si quelque chose cloche. **Conclusion** : s’entraîner intelligemment, c’est alterner effort et récupération."}$exo$::jsonb),
  ('21dd452b-bb68-53aa-990d-5157740fdf42'::uuid, 1, 'redaction', $exo${"titre":"Force, volume, endurance","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Complète pour **trois objectifs** (force maximale, hypertrophie, endurance de force) : nombre de répétitions, charge, repos.\n2. Que signifie la formule **puissance = force × vitesse** ? Cite une façon de la travailler.\n3. Donne la formule d’Epley et calcule le max estimé d’un élève qui soulève **60 kg pour 10 répétitions**.","bareme":[{"critere":"Trois zones correctement renseignées (répétitions, charge, repos)","points":8},{"critere":"Puissance : produire de la force vite ; charges moyennes bougées vite ou pliométrie","points":6},{"critere":"Formule d’Epley exacte et calcul : 60 × (1 + 10 / 30) = 80 kg","points":6}],"dureeMin":8,"corrige":"1. **Force maximale** : 1 à 5 répétitions, 85 % du max et plus, repos de 2 à 5 min. **Hypertrophie** : 6 à 12 répétitions, 65 à 85 %, repos de 60 à 90 s. **Endurance de force** : 15 répétitions et plus, moins de 60 %, repos court.\n\n2. La **puissance** est la **force multipliée par la vitesse** : savoir produire de la force **vite**. Un sujet très fort mais lent n’est pas puissant. On la travaille avec des **charges moyennes soulevées le plus vite possible** ou avec la **pliométrie** (sauts, bonds, lancers de médecine-ball).\n\n3. **Epley** : charge × (1 + répétitions / 30). Ici : 60 × (1 + 10 / 30) = 60 × 1,33 = **80 kg** environ. C’est une estimation qui évite de tester son maximum."}$exo$::jsonb),
  ('21dd452b-bb68-53aa-990d-5157740fdf42'::uuid, 2, 'redaction', $exo${"titre":"Une séance commentée","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Lina, 16 ans, vient de s’inscrire à la salle. Voici sa séance du lundi : *« Pas d’échauffement. Squat à la charge maximale : 1 répétition. Soulevé de terre en arrondissant le dos pour aller plus vite. Elle ressent une vive douleur au genou à la 3e série mais termine quand même. »*\n\n1. Relève **trois erreurs** de Lina et explique pourquoi elles posent problème **à son âge**.\n2. Elle veut travailler l’**hypertrophie** des cuisses : quelle zone de répétitions, de charge et de repos lui conseilles-tu ?\n3. Décris une séance « corps entier » raisonnable pour elle (gestes, séries, fréquence).","bareme":[{"critere":"Trois erreurs relevées (pas d’échauffement, charge max, dos rond, douleur ignorée) avec explication liée à l’âge","points":8},{"critere":"Zone d’hypertrophie correcte : 6 à 12 répétitions, 65 à 85 %, repos 60 à 90 s","points":5},{"critere":"Séance corps entière cohérente : échauffement, gestes de base, séries, trois séances et repos entre","points":7}],"dureeMin":12,"corrige":"1. **Charge maximale** : à 16 ans le squelette n’a pas fini de se solidifier, on monte les charges **progressivement** et on ne cherche **pas de charge maximale**. **Dos rond** sous charge : signal d’alerte, on **pose la barre** (le soulevé de terre se fait dos plat, barre près des jambes). **Douleur articulaire vive** au genou : on s’arrête, on ne termine pas ; une douleur d’articulation n’est pas une simple fatigue musculaire. (On peut aussi relever l’**absence d’échauffement** : 10 minutes sont nécessaires.)\n\n2. Pour l’**hypertrophie** : **6 à 12 répétitions**, avec **65 à 85 %** du max, et **60 à 90 s** de repos entre les séries.\n\n3. **Échauffement de dix minutes**, puis squat (4 × 8), développé couché (3 × 8), tirage (3 × 10), soulevé de terre léger (3 × 6), gainage pour finir, avec une technique **encadrée** par un adulte compétent. **Trois séances par semaine**, avec un **jour de repos** entre chaque, suffisent à progresser."}$exo$::jsonb),
  ('21dd452b-bb68-53aa-990d-5157740fdf42'::uuid, 3, 'redaction', $exo${"titre":"Soulever lourd à 16 ans ?","consigne":"Rédige une réponse argumentée, avec des exemples précis tirés du cours.","enonce":"Un camarade dit : *« Pour être fort, il faut tester sa charge maximale dès le début et soulever le plus lourd possible, même sans surveillance. La technique, on verra plus tard. »*\n\nRédige une réponse argumentée qui : **(1)** explique les risques de cette méthode à 16-18 ans ; **(2)** propose une alternative sûre pour estimer son max (avec la formule) ; **(3)** montre, en distinguant force, hypertrophie et puissance, que « être fort » ne se travaille pas partout de la même façon.","bareme":[{"critere":"Risques à 16-18 ans : squelette en cours de solidification, technique encadrée, dos rond, douleur articulaire","points":6},{"critere":"Alternative sûre : estimation par la formule d’Epley, avec exemple chiffré","points":5},{"critere":"Distinction des trois objectifs (répétitions, charge, repos) et de la puissance = force × vitesse","points":6},{"critere":"Argumentation structurée et conclusion","points":3}],"dureeMin":15,"corrige":"**Réponse attendue.** Cette méthode est dangereuse à notre âge. Le **squelette n’a pas fini de se solidifier** : on monte les charges **progressivement**, la technique doit être **encadrée** par un adulte compétent et on ne cherche **pas de charge maximale** avant la maturité du squelette. Soulever lourd sans surveillance et sans technique expose au **dos rond** sous charge et aux **douleurs articulaires** vives (genou, épaule, lombaires) : ce sont des signaux d’alerte qui imposent de **poser la barre**. La technique ne vient pas « plus tard » : c’est elle qui protège.\n\nOn peut pourtant connaître son niveau sans prendre de risque, avec la **formule d’Epley** : charge × (1 + répétitions / 30). Un élève qui soulève 60 kg pour 10 répétitions a un max d’environ 60 × (1 + 10 / 30), soit **80 kg**. C’est une estimation qui sert à choisir ses charges sans aller au bout de soi-même.\n\nEnfin, « être fort » recouvre plusieurs objectifs. La **force maximale** se travaille lourd et court (**1 à 5 répétitions**, 85 % et plus, repos de 2 à 5 min). L’**hypertrophie** se travaille à charge moyenne (**6 à 12 répétitions**, 65 à 85 %, repos de 60 à 90 s). L’**endurance de force** se travaille léger et long (**15 répétitions et plus**, moins de 60 %). La **puissance** est la **force multipliée par la vitesse** : charges moyennes bougées vite, pliométrie. **Conclusion** : à 16 ans, on progresse sans maximum, avec une technique propre, des charges progressives et un adulte compétent."}$exo$::jsonb),
  ('f1bc637c-5cea-5b98-981c-23940f3e3230'::uuid, 1, 'redaction', $exo${"titre":"Manger comme un sportif","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Nomme les **trois macronutriments** et le rôle principal de chacun.\n2. Donne les quantités repères de **glucides** et de **protéines** par kilo et par jour pour un sportif régulier. Comment doit-on répartir les protéines ?\n3. Pourquoi faut-il s’hydrater avant d’avoir soif ? Cite le seuil de perte de poids qui fait baisser la performance.","bareme":[{"critere":"Trois macronutriments avec leur rôle (carburant de l’intensité, réparer/construire, énergie de fond)","points":6},{"critere":"Glucides 5 à 7 g/kg/jour ; protéines 1,2 à 2 g/kg/jour réparties sur la journée","points":8},{"critere":"Hydratation : perte de 2 % du poids en eau, boire par petites gorgées régulières","points":6}],"dureeMin":8,"corrige":"1. Les **glucides** sont le carburant de l’intensité ; les **protéines** servent à réparer et construire les muscles ; les **lipides** fournissent l’énergie de fond (et servent aux hormones et aux cellules).\n\n2. **Glucides** : **5 à 7 g par kilo et par jour**. **Protéines** : **1,2 à 2 g par kilo et par jour**, **réparties sur la journée**, pas avalées en une seule fois. L’assiette suffit.\n\n3. Une perte de **2 % du poids du corps** en eau suffit à faire **baisser la performance**. On boit avant, pendant et après, par petites gorgées régulières, **sans attendre d’avoir soif**."}$exo$::jsonb),
  ('f1bc637c-5cea-5b98-981c-23940f3e3230'::uuid, 2, 'redaction', $exo${"titre":"Le plateau de la veille de match","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"La veille d’un match, deux joueurs mangent au self. **Adam** prend une grosse portion de pâtes, du poisson, des légumes, un yaourt, une pomme et de l’eau. **Théo** prend une barre protéinée, une canette de boisson énergisante et dit : *« J’ai acheté de la créatine, je la teste demain matin, comme ça je serai surpris. »*\n\n1. Compare les deux plateaux : lequel prépare le mieux le match ? Justifie avec les rôles des nutriments.\n2. Relève **deux erreurs** de Théo (boisson, créatine, nouveauté) en citant ce que dit le cours.\n3. Explique pourquoi un complément alimentaire peut mettre un sportif en danger, même s’il est acheté en magasin.","bareme":[{"critere":"Plateau d’Adam justifié : féculents (glucides), protéines, légumes, produit laitier, fruit, eau","points":7},{"critere":"Deux erreurs de Théo relevées avec la règle du cours (énergisantes déconseillées, créatine avant 18 ans, pas de nouveauté le jour J)","points":7},{"critere":"Compléments pouvant contenir des substances dopantes ; contrôle positif involontaire, athlète responsable","points":6}],"dureeMin":12,"corrige":"1. Le plateau d’**Adam** est le bon : les **pâtes** apportent des **glucides** (le carburant de l’intensité), le poisson des **protéines** pour réparer, les légumes, le yaourt et le fruit complètent, et l’**eau** couvre l’hydratation. L’**assiette suffit**. Théo se prive de glucides en quantité et ne s’hydrate pas correctement.\n\n2. Les **boissons énergisantes** sont **déconseillées aux adolescents par l’ANSES**. La **créatine** est efficace et étudiée chez l’adulte, mais **pas conseillée avant 18 ans sans avis médical**. On ne teste **jamais un aliment ou un produit inconnu avant une compétition** : pas de nouveauté le jour J.\n\n3. Certains **compléments** contiennent des **substances dopantes non indiquées** sur l’étiquette. Un **contrôle positif « involontaire »** reste un contrôle positif : l’athlète est **responsable de ce qu’il avale**."}$exo$::jsonb),
  ('f1bc637c-5cea-5b98-981c-23940f3e3230'::uuid, 3, 'redaction', $exo${"titre":"Le vrai et le faux","consigne":"Rédige une réponse argumentée, avec des exemples précis tirés du cours.","enonce":"Un camarade affirme : *« Pour progresser en sport, il faut manger un maximum de protéines dans les 30 minutes après l’entraînement, prendre de la créatine et des boissons énergisantes, et faire un régime strict pour être plus léger. »*\n\nRédige une réponse argumentée qui : **(1)** examine chaque idée reçue en distinguant le vrai et le faux ; **(2)** rappelle les quantités et la répartition des nutriments qui comptent vraiment ; **(3)** propose le repas et les habitudes d’hydratation autour d’un effort (avant, pendant, après).","bareme":[{"critere":"Idées reçues réfutées : fenêtre anabolique moins stricte, créatine, énergisantes, régime/jeûne pendant la croissance","points":8},{"critere":"Quantités : glucides 5 à 7 g/kg/jour, protéines 1,2 à 2 g/kg/jour réparties sur la journée","points":4},{"critere":"Avant (repas riche en glucides vers 3 h), pendant (eau), après (glucides + protéines) et hydratation","points":5},{"critere":"Argumentation structurée et conclusion","points":3}],"dureeMin":15,"corrige":"**Réponse attendue.** Aucune de ces idées n’est à suivre telle quelle. La « **fenêtre anabolique** » de 30 minutes est **moins stricte qu’on le dit** : c’est le **total de la journée** qui compte davantage. La **créatine** est efficace et étudiée chez l’adulte, mais **pas conseillée avant 18 ans sans avis médical**. Les **boissons énergisantes** sont **déconseillées aux adolescents par l’ANSES**. Quant au **régime** ou au **jeûne** pour être plus léger, il faut les **éviter pendant la croissance**.\n\nCe qui compte vraiment : les **glucides**, carburant de l’intensité (**5 à 7 g/kg/jour** pour un sportif régulier), et les **protéines** (**1,2 à 2 g/kg/jour**) surtout **réparties sur la journée**. Un repas normal en apporte déjà beaucoup : l’**assiette suffit**. À cela s’ajoute l’**hydratation** : perdre 2 % de son poids en eau fait déjà baisser la performance.\n\nAutour de l’effort : **avant**, un repas riche en glucides environ **trois heures** avant ; **pendant**, de l’eau par petites gorgées, et un peu de glucides si l’effort est long ; **après**, des **glucides** pour refaire les stocks et des **protéines** pour réparer. On ne teste jamais un aliment inconnu avant une compétition. Enfin, certains **compléments** contiennent des substances dopantes non indiquées, et le sportif est responsable de ce qu’il avale. **Conclusion** : une alimentation variée et une bonne hydratation valent mieux que les produits miracles."}$exo$::jsonb),
  ('e270f3b1-967c-5a19-9e3c-05e83ee12861'::uuid, 1, 'redaction', $exo${"titre":"Reconnaître les blessures","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Qu’est-ce qu’une **entorse** ? Quelle articulation est la plus touchée et combien y a-t-il de grades ?\n2. Que signifie en réalité le mot « **tendinite** » dans la plupart des cas ?\n3. Cite trois **signes** d’une commotion cérébrale et la règle à appliquer.","bareme":[{"critere":"Entorse : lésion d’un ligament, cheville la plus touchée, trois grades","points":7},{"critere":"Tendinopathie de surcharge : trop d’effort, trop vite","points":6},{"critere":"Trois signes de commotion (maux de tête, confusion, nausées, troubles de la vue) et « au moindre doute, on sort »","points":7}],"dureeMin":7,"corrige":"1. Une **entorse** est une lésion d’un **ligament**, la bande qui tient l’articulation. La **cheville** est la plus touchée. Il y a **trois grades** : étirement, déchirure partielle, rupture complète.\n\n2. La plupart du temps, une « tendinite » est une **tendinopathie de surcharge** : le tendon a reçu **trop d’effort, trop vite**.\n\n3. Signes : **maux de tête**, **confusion**, **nausées**, **troubles de la vue**. Règle : **au moindre doute, on sort** ; le joueur ne finit jamais le match."}$exo$::jsonb),
  ('e270f3b1-967c-5a19-9e3c-05e83ee12861'::uuid, 2, 'redaction', $exo${"titre":"Trois scènes de vestiaire","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"**Scène 1.** En basket, Noa retombe mal : sa cheville gonfle. **Scène 2.** Léa, coureuse, a le tendon d’Achille qui tire depuis qu’elle a doublé ses distances en deux semaines. **Scène 3.** En rugby, Karim reçoit un choc à la tête. Il dit « ça va » mais se répète et a mal à la tête.\n\n1. Scène 1 : de quelle blessure s’agit-il probablement ? Quels gestes immédiats puis quelle suite ?\n2. Scène 2 : quelle est la vraie nature de la douleur de Léa, son origine et ce qu’elle doit faire ?\n3. Scène 3 : que fait l’entraîneur et pourquoi ? Décris le retour au jeu.\n4. Cite trois situations où il faut consulter un médecin.","bareme":[{"critere":"Entorse identifiée ; conduite PEACE & LOVE : protéger, comprimer, surélever, éduquer, puis remise en mouvement progressive","points":5},{"critere":"Tendinopathie de surcharge (trop, trop vite) ; adapter la charge et renforcer progressivement","points":4},{"critere":"Commotion : sortie immédiate, repos puis reprise par paliers sur plusieurs semaines ; second choc dangereux","points":6},{"critere":"Trois cas de consultation (douleur persistante, articulation bloquée, gonflement important, douleur nocturne, choc à la tête)","points":5}],"dureeMin":12,"corrige":"1. **Entorse** de la cheville (lésion d’un ligament). Gestes immédiats : **PEACE & LOVE** : on **protège** la zone au début, on **comprime**, on **surélève**, on **éduque** (pas de panique). Puis, très vite, **remise en mouvement progressive**, sans douleur vive, car l’articulation a besoin de bouger pour guérir.\n\n2. Il s’agit d’une **tendinopathie de surcharge** : le tendon a reçu **trop d’effort, trop vite**. Léa doit **adapter la charge** et **renforcer progressivement**, plutôt que tout arrêter.\n\n3. **Au moindre doute, on sort** : Karim ne finit **pas** le match, même s’il dit aller bien, car il peut cacher ses symptômes. Retour par **repos, puis reprise progressive par paliers**, sur **plusieurs semaines** pour un mineur. Un **second choc** sur un cerveau fragilisé peut être grave.\n\n4. On consulte quand la douleur **persiste**, quand une articulation (genou, cheville) se **bloque**, quand le **gonflement** est important, quand la douleur **réveille la nuit** ou en cas de symptômes après un **choc à la tête**."}$exo$::jsonb),
  ('e270f3b1-967c-5a19-9e3c-05e83ee12861'::uuid, 3, 'redaction', $exo${"titre":"Au moindre doute, on sort","consigne":"Rédige une réponse argumentée, avec des exemples précis tirés du cours.","enonce":"Pendant un match, un joueur de 16 ans reçoit un coup à la tête. Son entraîneur veut le laisser jouer : *« Il dit qu’il va bien, c’est un battant, et on a besoin de lui. Une commotion, ce n’est qu’un petit coup. »* Un coéquipier estime au contraire qu’il faut le sortir.\n\nRédige une réponse argumentée qui : **(1)** donne raison à l’un des deux et justifie avec les signes et les risques d’une commotion ; **(2)** explique qui doit agir et pourquoi le joueur ne peut pas décider seul ; **(3)** décrit le retour au jeu et la prévention des blessures en général.","bareme":[{"critere":"Position justifiée : on sort le joueur, signes de commotion, second choc grave","points":6},{"critere":"Rôle de l’entraîneur, des coéquipiers et de l’arbitre ; le sportif peut cacher ses symptômes par peur de décevoir","points":5},{"critere":"Retour par repos puis paliers sur plusieurs semaines pour un mineur ; consultation médicale","points":5},{"critere":"Prévention (échauffement, progressivité, renforcement, sommeil, hydratation) et qualité de la rédaction","points":4}],"dureeMin":15,"corrige":"**Réponse attendue.** Le coéquipier a raison : **au moindre doute, on sort**. Après un choc à la tête, la **commotion** se reconnaît à plusieurs signes : **maux de tête**, **confusion**, **nausées**, **troubles de la vue**. Ici, un joueur qui dit « ça va » mais qui se répète ou a mal à la tête présente justement ces signes. Il ne doit **jamais** finir le match, même s’il affirme aller bien : un **second choc** sur un cerveau déjà fragilisé peut être **grave**.\n\nLe joueur ne peut pas décider seul : un sportif qui a peur de décevoir ou qui veut aider son équipe peut **cacher ses symptômes**. C’est donc à l’**entraîneur**, aux **coéquipiers** et à l’**arbitre** d’agir à sa place. Un match ne vaut jamais un cerveau abîmé.\n\nLe retour au jeu se fait par **repos, puis reprise progressive par paliers**, et prend **plusieurs semaines pour un mineur**. Après des symptômes consécutifs à un choc à la tête, on **consulte un médecin** : on ne s’improvise pas kiné.\n\nPlus largement, **prévenir vaut mieux que guérir** : l’**échauffement**, la **progressivité** de la charge (la tendinopathie vient de « trop, trop vite »), le **renforcement**, le **sommeil** et l’**hydratation** sont la première assurance contre la blessure. **Conclusion** : la santé du joueur passe avant le résultat, et c’est tout le groupe qui en est responsable."}$exo$::jsonb),
  ('78dffff4-cbfc-5911-95cb-6520d0db2c2d'::uuid, 1, 'redaction', $exo${"titre":"Aux origines du sport moderne","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Dans quel pays et à quel siècle naît le sport moderne ? Qu’est-ce qui le distingue des anciens jeux de balle ?\n2. Associe chaque date à son événement : 1863, 1871, 1874, 1877.\n3. Cite deux clubs français créés par des Anglais installés en France, avec leur date.","bareme":[{"critere":"Angleterre, XIXe siècle ; règles écrites communes, clubs, fédérations","points":6},{"critere":"Quatre dates associées : Football Association 1863, Rugby Football Union 1871, brevet du lawn-tennis 1874, Wimbledon 1877","points":8},{"critere":"Deux clubs français datés (Le Havre AC 1872, Racing Club de France 1882, Stade français 1883)","points":6}],"dureeMin":7,"corrige":"1. Le sport moderne naît en **Angleterre** au **XIXe siècle**, dans les **public schools**. Ce qui le distingue : des **règles codifiées** (écrites, les mêmes pour tous), des **clubs** et des **fédérations**, pour que des équipes de lieux différents puissent s’affronter.\n\n2. **1863** : création de la **Football Association**. **1871** : création de la **Rugby Football Union**. **1874** : brevet du **lawn-tennis**. **1877** : premier tournoi de **Wimbledon**.\n\n3. Le **Havre Athletic Club** (1872), le **Racing Club de France** (1882), le **Stade français** (1883)."}$exo$::jsonb),
  ('78dffff4-cbfc-5911-95cb-6520d0db2c2d'::uuid, 2, 'redaction', $exo${"titre":"Des Anglais aux associations","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Extrait imaginé de journal local, 1884 : *« Place de la mairie, des jeunes gens en maillot tapent dans une balle. Ils viennent d’un club fondé par des Anglais. Au collège voisin, les élèves, eux, font toujours de la gymnastique en rang, au son du tambour. »*\n\n1. Pourquoi les jeunes Français jouent-ils à ces jeux ? D’où viennent-ils ?\n2. Distingue **gymnastique** et **sport anglais**, en précisant ce que la gymnastique cherchait à former en France.\n3. Explique la différence entre un **amateur** et un **professionnel** à cette époque.\n4. En quoi la **loi de 1901** a-t-elle changé le sport en France ? Cite aussi un apport du **Front populaire** (1936).","bareme":[{"critere":"Diffusion par des Anglais installés en France ; clubs de 1872 à 1883","points":4},{"critere":"Gymnastique (Turnen allemand, bataillons scolaires, corps forts pour la patrie) opposée au sport plus libre et ludique","points":6},{"critere":"Amateurs jouent par plaisir sans être payés ; professionnels payés, mal vus","points":4},{"critere":"Loi de 1901 (associations, milliers de clubs) et Front populaire (Léo Lagrange, congés payés, sport pour tous)","points":6}],"dureeMin":12,"corrige":"1. Le sport vient d’**Angleterre** ; ce sont des **Anglais installés en France** qui apportent leurs jeux et fondent des clubs (Le Havre AC en 1872, Racing Club de France en 1882, Stade français en 1883).\n\n2. La **gymnastique**, inspirée du modèle allemand du **Turnen**, domine d’abord dans les écoles et les **bataillons scolaires** : elle vise à **former des corps forts pour la patrie**. Le **sport anglais**, plus libre et plus ludique, va peu à peu s’imposer.\n\n3. L’**amateur** joue par plaisir et n’est pas payé ; le **professionnel** est payé pour jouer et il est alors mal vu. Cette opposition va durer plus d’un siècle.\n\n4. La **loi de 1901** permet à n’importe qui de créer une **association** : des milliers de **clubs** apparaissent, base du sport français encore aujourd’hui. En **1936**, le **Front populaire** crée un sous-secrétariat d’État aux Sports et aux Loisirs confié à **Léo Lagrange** ; avec les **congés payés**, le sport devient accessible au plus grand nombre (auberges de jeunesse, sport pour tous)."}$exo$::jsonb),
  ('78dffff4-cbfc-5911-95cb-6520d0db2c2d'::uuid, 3, 'redaction', $exo${"titre":"Un sport « pour tous » ?","consigne":"Rédige une réponse argumentée, avec des exemples précis tirés du cours.","enonce":"Un élève affirme : *« Le sport a toujours été fait pour tout le monde, c’est naturel. Les Français ont inventé le football et le club est une vieille tradition. »*\n\nRédige une réponse argumentée qui : **(1)** corrige l’origine du sport moderne et explique pourquoi on dit « football » et pas « balle au pied » ; **(2)** retrace comment la France l’a adopté (gymnastique, clubs, loi de 1901) ; **(3)** montre, avec le Front populaire et l’organisation après 1945, que le sport pour tous est une conquête récente.","bareme":[{"critere":"Origine anglaise (public schools, règles codifiées, FA 1863, RFU 1871) ; mots anglais conservés","points":6},{"critere":"Adoption française : Anglais installés en France, clubs dès 1872, gymnastique avant le sport, loi de 1901","points":6},{"critere":"Sport pour tous = conquête récente : Front populaire 1936, congés payés ; après 1945 ministère, fédérations, UNSS","points":5},{"critere":"Argumentation structurée et conclusion","points":3}],"dureeMin":15,"corrige":"**Réponse attendue.** L’affirmation est fausse sur deux points. D’abord, le sport moderne n’a pas été inventé en France : il naît en **Angleterre** au **XIXe siècle**. Dans les **public schools**, on joue à des jeux de balle aux règles locales ; pour que des équipes de lieux différents puissent s’affronter, il faut des **règles écrites communes**. D’où la **Football Association** (1863), la **Rugby Football Union** (1871), le brevet du **lawn-tennis** (1874) et **Wimbledon** (1877). Voilà pourquoi on dit « **football** », « tennis », « rugby », « match », « penalty » : les mots sont restés anglais, car le sport est né avec ses règles et ses clubs.\n\nLa France l’adopte ensuite : ce sont des **Anglais installés en France** qui apportent leurs jeux (**Le Havre AC** en 1872, **Racing Club de France** en 1882, **Stade français** en 1883). Auparavant, c’est la **gymnastique**, venue du modèle allemand du **Turnen**, qui domine dans les écoles et les **bataillons scolaires**, pour former des corps forts pour la patrie. La **loi de 1901** permet de créer des **associations** : des milliers de clubs naissent, encore la base du sport français.\n\nEnfin, le sport n’a **pas toujours été « pour tout le monde »** : au départ réservé à une élite, avec des **amateurs** valorisés et des **professionnels** mal vus, il devient accessible avec le **Front populaire** (1936, **Léo Lagrange**, **congés payés**, **auberges de jeunesse**). Après **1945**, l’État organise le sport : **ministère**, **fédérations**, **mouvement sportif**, et le sport scolaire (**UNSS**). **Conclusion** : le sport pour tous est une conquête, et elle est récente."}$exo$::jsonb),
  ('e37c9cb1-203b-566b-b39b-917ad4cb95c6'::uuid, 1, 'redaction', $exo${"titre":"Jeux et événements politiques","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Que s’est-il passé sur le podium du 200 m à Mexico le 16 octobre 1968 ? Cite les trois athlètes.\n2. Pourquoi les Jeux de Berlin 1936 sont-ils un exemple de propagande ? Quel athlète les a marqués et avec quel résultat ?\n3. Associe les années 1972, 1980 et 1984 à l’événement qui les caractérise.","bareme":[{"critere":"Mexico 1968 : poing levé de Tommie Smith et John Carlos, Peter Norman solidaire, dénonciation du sort des Noirs américains","points":7},{"critere":"Berlin 1936 : Hitler, vitrine du régime ; Jesse Owens, quatre médailles d’or","points":6},{"critere":"Munich 1972 attentat (onze morts), Moscou 1980 boycott, Los Angeles 1984 boycott soviétique","points":7}],"dureeMin":7,"corrige":"1. À Mexico, **Tommie Smith** et **John Carlos** montent chacun un **poing ganté de noir** pendant l’hymne, pour dénoncer le sort des **Noirs américains**. Le deuxième, l’Australien **Peter Norman**, se montre **solidaire**.\n\n2. Berlin 1936 : les Jeux se tiennent dans l’Allemagne d’**Hitler**, qui en fait une **vitrine de propagande** nazie (filmée par Leni Riefenstahl). Mais l’athlète noir américain **Jesse Owens** gagne **quatre médailles d’or** et ruine le discours sur la supériorité d’une prétendue race.\n\n3. **1972, Munich** : attentat contre l’équipe d’**Israël**, **onze** membres de la délégation tués. **1980, Moscou** : boycott d’une soixantaine de pays après l’invasion de l’Afghanistan par l’URSS. **1984, Los Angeles** : boycott de l’URSS et de ses alliés."}$exo$::jsonb),
  ('e37c9cb1-203b-566b-b39b-917ad4cb95c6'::uuid, 2, 'redaction', $exo${"titre":"Lire un geste politique","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Document : *photographie de 1968, trois hommes sur un podium. Deux d’entre eux, tête baissée, tendent un poing ganté de noir pendant l’hymne américain. Le troisième porte le même badge qu’eux.*\n\n1. Identifie la scène (lieu, date, sportifs) et explique le **message** des deux Américains.\n2. Rappelle ce que fait le troisième athlète et pourquoi son geste compte.\n3. Compare ce geste à la politique d’un **État** qui organise les Jeux : explique l’intérêt de Hitler en 1936 et celui du pouvoir chinois en 2008.\n4. Donne deux exemples où le sport a servi d’**arme** ou de **pont** diplomatique (boycott, apartheid, ping-pong).","bareme":[{"critere":"Scène identifiée (Mexico, 16 octobre 1968, Smith et Carlos) et message sur le sort des Noirs américains","points":5},{"critere":"Peter Norman solidaire des deux Américains","points":3},{"critere":"Vitrine de propagande en 1936 et de puissance en 2008 : image d’un État grâce aux Jeux","points":6},{"critere":"Deux exemples diplomatiques (boycotts 1980/1984, Afrique du Sud exclue 1964-1992, ping-pong 1971)","points":6}],"dureeMin":12,"corrige":"1. La photographie montre le podium du 200 m à **Mexico**, le **16 octobre 1968**. **Tommie Smith** et **John Carlos** lèvent le poing ganté pour **dénoncer le sort des Noirs américains** : un geste politique devant le monde entier.\n\n2. Le troisième est l’Australien **Peter Norman**, deuxième du 200 m, qui se montre **solidaire** des deux Américains en portant leur badge. Il montre que le geste n’est pas isolé.\n\n3. En **1936**, **Hitler** fait des Jeux une **vitrine pour la propagande** nazie. En **2008**, les Jeux de **Pékin** sont une **vitrine du pouvoir chinois**. Organiser un grand événement, c’est montrer sa **puissance**, son organisation et son **image**.\n\n4. Le sport peut servir d’arme : **boycott** de Moscou en 1980 (une soixantaine de pays, après l’invasion de l’Afghanistan) et de Los Angeles en 1984 (URSS et alliés) ; l’**Afrique du Sud**, pays de l’apartheid, exclue des Jeux de 1964 à 1992. Il peut aussi être un pont : la « **diplomatie du ping-pong** » de 1971 rapproche États-Unis et Chine."}$exo$::jsonb),
  ('e37c9cb1-203b-566b-b39b-917ad4cb95c6'::uuid, 3, 'redaction', $exo${"titre":"Le sport est-il neutre ?","consigne":"Rédige une réponse argumentée, avec des exemples précis tirés du cours.","enonce":"Un élève affirme : *« Le sport doit rester à l’écart de la politique. Quand un athlète lève le poing ou qu’un pays boycotte les Jeux, il gâche le spectacle : les Jeux, c’est juste du sport. »*\n\nRédige une réponse argumentée qui : **(1)** montre, avec au moins trois événements précis (dates, noms), que le sport n’a jamais été neutre ; **(2)** distingue le sport utilisé par un État (propagande, boycott) et le sport utilisé par les athlètes (gestes) ; **(3)** donne un exemple actuel (Russie, Qatar) et conclut.","bareme":[{"critere":"Au moins trois événements précis et datés (Berlin 1936, Mexico 1968, Munich 1972, boycotts 1980/1984, apartheid…)","points":7},{"critere":"Distinction : l’État qui utilise le sport (vitrine, boycott) / les athlètes qui s’en servent pour s’exprimer","points":5},{"critere":"Exemple actuel : Russie suspendue depuis 2022 et athlètes neutres à Paris 2024, ou Qatar 2022 et droits humains","points":4},{"critere":"Argumentation structurée et conclusion nuancée","points":4}],"dureeMin":15,"corrige":"**Réponse attendue.** Cette affirmation ne tient pas : de toute son histoire, le sport est un **message politique**. En **1936**, Berlin est une **vitrine pour la propagande** d’Hitler ; pourtant **Jesse Owens**, athlète noir, gagne **quatre médailles d’or** et ruine le discours sur la supériorité d’une prétendue race. En **1968**, à Mexico, **Tommie Smith** et **John Carlos** lèvent le **poing** pour dénoncer le sort des Noirs américains, soutenus par **Peter Norman**. En **1972**, à Munich, un commando tue **onze** membres de l’équipe d’**Israël**. En **1980** et **1984**, les **boycotts** de Moscou (après l’invasion de l’Afghanistan) et de Los Angeles opposent les deux blocs. L’**Afrique du Sud**, pays de l’apartheid, est **exclue des Jeux de 1964 à 1992**.\n\nIl faut distinguer deux usages. Les **États** utilisent le sport pour montrer leur **puissance** et leur **image** (Berlin 1936, Pékin 2008) ou pour punir (boycotts). Les **athlètes**, eux, s’en servent pour **s’exprimer**, comme à Mexico. Le sport peut aussi rapprocher : la **diplomatie du ping-pong** de 1971 ouvre une porte entre États-Unis et Chine.\n\nAujourd’hui encore : la **Russie** est **suspendue depuis 2022** et ses athlètes concourent à **Paris 2024** sous bannière « **neutre** » ; la Coupe du monde **Qatar 2022** relance le débat sur les **droits humains**. **Conclusion** : un grand événement sportif est toujours un message politique ; mais le sport peut aussi diviser autant qu’il ouvre des portes que la diplomatie n’ose pas encore pousser."}$exo$::jsonb),
  ('b0e6ec43-5992-585f-9768-bd8583076743'::uuid, 1, 'redaction', $exo${"titre":"Une frise de conquêtes","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Combien de femmes concourent aux Jeux de Paris en 1900 ? Qui gagne en tennis ?\n2. Qui est **Alice Milliat** ? Cite ce qu’elle fonde en 1921 et ce qu’elle organise en 1922.\n3. Associe 1967, 1973 et 1984 à la personne et à l’événement.","bareme":[{"critere":"1900 : 22 femmes ; Charlotte Cooper gagne en tennis","points":5},{"critere":"Alice Milliat : FSFI (1921) et Jeux mondiaux féminins à Paris (1922), face à Coubertin hostile","points":7},{"critere":"1967 Kathrine Switzer à Boston ; 1973 Billie Jean King bat Bobby Riggs ; 1984 Joan Benoit, premier marathon olympique féminin","points":8}],"dureeMin":7,"corrige":"1. **22 femmes** concourent aux Jeux de Paris en 1900 ; **Charlotte Cooper** gagne en tennis.\n\n2. **Alice Milliat** (1884-1957) est la pionnière du sport féminin. Face à **Coubertin**, hostile à la présence des femmes, elle fonde la **FSFI** en **1921** et organise les **Jeux mondiaux féminins** à **Paris** en **1922**.\n\n3. **1967** : **Kathrine Switzer** court le marathon de **Boston** avec un dossard. **1973** : **Billie Jean King** bat **Bobby Riggs** (la « bataille des sexes »). **1984** : **Joan Benoit** remporte le premier **marathon olympique féminin**."}$exo$::jsonb),
  ('b0e6ec43-5992-585f-9768-bd8583076743'::uuid, 2, 'redaction', $exo${"titre":"Lire une frise","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Frise : *1900 — 22 femmes aux Jeux · 1921 — FSFI · 1922 — Jeux mondiaux féminins · 1928 — athlétisme féminin aux Jeux · 1960 — retour du 800 m · 1984 — marathon olympique féminin · 2024 — Jeux de Paris.*\n\n1. Que s’est-il passé en 1928 pour l’athlétisme féminin ? Quelle épreuve en est retirée jusqu’en 1960 et pourquoi ?\n2. Explique pourquoi les Jeux mondiaux féminins de 1922 sont une réponse à l’attitude de Coubertin.\n3. Que signifie « premiers Jeux à parité » en 2024 ? La parité suffit-elle à parler d’égalité ? Donne trois exemples d’inégalités restantes.\n4. Cite deux championnes françaises actuelles avec leur sport.","bareme":[{"critere":"1928 : athlétisme féminin aux Jeux ; 800 m retiré jusqu’en 1960 car jugé « trop dur »","points":5},{"critere":"Milliat répond à l’hostilité de Coubertin en créant ses propres Jeux : « on ouvre une autre porte »","points":5},{"critere":"Parité 2024 ≠ égalité ; inégalités : médiatisation, primes, dirigeantes","points":6},{"critere":"Deux championnes françaises avec leur sport (Henry, Renard, Agbegnenou, Ferrand-Prévot)","points":4}],"dureeMin":12,"corrige":"1. En **1928**, l’**athlétisme féminin** entre aux Jeux. Mais le **800 m** est **retiré du programme jusqu’en 1960**, sous prétexte que l’épreuve serait « **trop dure** » pour les femmes.\n\n2. **Coubertin** est hostile à la présence des femmes aux Jeux. **Alice Milliat** répond en créant la **FSFI** (1921) puis ses propres **Jeux mondiaux féminins** (Paris, 1922) : quand on ferme une porte, on en ouvre une autre.\n\n3. Paris 2024 : les premiers Jeux à **parité** entre athlètes femmes et hommes. Mais parité ne veut pas dire égalité partout : la **médiatisation**, les **primes** et la présence de **femmes dirigeantes** restent plus faibles chez les femmes.\n\n4. **Amandine Henry** ou **Wendie Renard** (football), **Clarisse Agbegnenou** (judo), **Pauline Ferrand-Prévot** (cyclisme)."}$exo$::jsonb),
  ('b0e6ec43-5992-585f-9768-bd8583076743'::uuid, 3, 'redaction', $exo${"titre":"Le sport est-il fait pour les femmes ?","consigne":"Rédige une réponse argumentée, avec des exemples précis tirés du cours.","enonce":"Un élève affirme : *« Si les femmes n’ont pas participé plus tôt aux Jeux, c’est parce qu’elles n’étaient pas intéressées ou pas capables. Aujourd’hui, avec la parité aux Jeux, tout est réglé. »*\n\nRédige une réponse argumentée qui : **(1)** montre, avec une frise de dates précises, que les obstacles étaient une décision et non un manque d’envie ; **(2)** met en valeur au moins trois femmes (noms, gestes) ; **(3)** explique ce qui reste inégal malgré la parité de 2024.","bareme":[{"critere":"Frise datée de 1900 à 2024 : obstacles voulus (Coubertin, 800 m retiré jusqu’en 1960)","points":6},{"critere":"Au moins trois femmes citées avec leur geste (Milliat, Switzer, Billie Jean King, Joan Benoit, Cooper)","points":6},{"critere":"Inégalités restantes : médiatisation, primes, dirigeantes ; Première Ligue 2024 comme progrès","points":5},{"critere":"Argumentation structurée et conclusion","points":3}],"dureeMin":15,"corrige":"**Réponse attendue.** C’est faux : les femmes ont toujours voulu pratiquer, mais on leur a barré la route. En **1900**, seulement **22 femmes** sont autorisées aux Jeux de Paris (**Charlotte Cooper** gagne en tennis). **Coubertin**, fondateur des Jeux modernes, est **hostile** à leur présence. **Alice Milliat** (1884-1957) fonde alors la **FSFI** en **1921** et organise les **Jeux mondiaux féminins** à Paris en **1922**. En **1928**, l’athlétisme féminin entre enfin aux Jeux, mais le **800 m** est **retiré jusqu’en 1960**, jugé « **trop dur** ».\n\nD’autres gestes font avancer les choses : en **1967**, **Kathrine Switzer** court le marathon de **Boston** avec un dossard ; en **1973**, **Billie Jean King** bat **Bobby Riggs** dans la « **bataille des sexes** », événement mondial ; en **1984**, **Joan Benoit** gagne le premier **marathon olympique féminin**. En France, des championnes comme **Amandine Henry**, **Wendie Renard**, **Clarisse Agbegnenou** ou **Pauline Ferrand-Prévot** sont connues du grand public, et le football féminin devient professionnel en **2024** (**Première Ligue**).\n\nMais la **parité** atteinte à **Paris 2024**, premiers Jeux à parité, ne veut pas dire égalité partout : la **médiatisation**, les **primes** et la présence de **femmes dirigeantes** restent plus faibles. **Conclusion** : le sport féminin est une conquête, menée par des femmes qui ont refusé qu’on leur dise « ce n’est pas fait pour vous », et elle n’est pas terminée."}$exo$::jsonb),
  ('fa152617-5e92-5951-8a25-f55e620590f7'::uuid, 1, 'redaction', $exo${"titre":"D’où vient l’argent du sport","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Cite **quatre sources** d’argent du sport et dis qui paie dans chaque cas.\n2. Que s’est-il passé en 2020 pour les droits TV de la Ligue 1 ? Quelle chaîne la Ligue a-t-elle lancée en 2025 ?\n3. Donne le record de transfert, le joueur et l’année. Depuis quand le PSG appartient-il au Qatar ?","bareme":[{"critere":"Quatre sources parmi droits TV, sponsors/équipementiers, billetterie, transferts, propriétaires, avec qui paie","points":7},{"critere":"Faillite de Mediapro en 2020 ; DAZN en 2024-25 ; Ligue 1+ en 2025","points":6},{"critere":"Neymar, 222 millions d’euros, 2017 ; PSG propriété du Qatar depuis 2011","points":7}],"dureeMin":7,"corrige":"1. **Droits TV** : les chaînes qui diffusent les matchs. **Sponsors et équipementiers** : des marques comme Nike ou Adidas. **Billetterie** : les spectateurs. **Transferts** : un club qui achète un joueur à un autre. (Aussi : les **propriétaires**, États ou fonds d’investissement.)\n\n2. En **2020**, **Mediapro** fait faillite, laissant la Ligue 1 sans diffuseur. **DAZN** arrive en 2024-25, puis la Ligue lance sa propre chaîne, **Ligue 1+**, en **2025**.\n\n3. Le record est celui de **Neymar**, acheté **222 millions d’euros** en **2017** par le PSG. Le PSG appartient au **Qatar depuis 2011**."}$exo$::jsonb),
  ('fa152617-5e92-5951-8a25-f55e620590f7'::uuid, 2, 'redaction', $exo${"titre":"Un budget olympique","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Extrait d’un article imaginé : *« Les Jeux de Paris 2024 ont un comité d’organisation au budget d’environ 4,4 milliards d’euros, financé surtout par le privé. Les infrastructures représentent environ 4,5 milliards. En 2025, la Cour des comptes a estimé le coût public à environ 6,6 milliards. »*\n\n1. Distingue les trois chiffres de l’article et dis qui paie dans chaque cas.\n2. Pourquoi faut-il rester **prudent** avec ces chiffres ?\n3. Le cours dit que les clubs sont aussi encadrés : quelle règle l’**UEFA** impose-t-elle et pourquoi ?\n4. Un maillot coûte 80 euros : indique à quels acteurs revient une part de ce prix.","bareme":[{"critere":"Budget du comité (≈ 4,4 Md€, surtout privé), infrastructures (≈ 4,5 Md€), coût public (≈ 6,6 Md€ selon la Cour des comptes)","points":7},{"critere":"Prudence : ce sont des estimations qui se discutent","points":4},{"critere":"UEFA : durabilité financière, on ne dépense pas durablement plus qu’on ne gagne ; compétition inégale sinon","points":5},{"critere":"Prix du maillot : équipementier, club (et joueurs), distributeur","points":4}],"dureeMin":12,"corrige":"1. Environ **4,4 milliards d’euros** pour le **comité d’organisation**, financés surtout par le **privé** ; environ **4,5 milliards** pour les **infrastructures** ; environ **6,6 milliards** de **coût public** estimé par la **Cour des comptes** en 2025.\n\n2. Ce sont des **estimations** : elles dépendent de ce qu’on compte et se **discutent**. On les formule donc avec prudence.\n\n3. L’**UEFA** impose des règles de **durabilité financière** : un club ne doit pas dépenser durablement plus qu’il ne gagne. Elles servent à éviter les excès, car quand l’argent d’un propriétaire est illimité, la compétition devient inégale.\n\n4. Une part revient à l’**équipementier**, une au **club** (et à ses joueurs), une au **distributeur** : le maillot est un produit de marque autant qu’un souvenir de supporter."}$exo$::jsonb),
  ('fa152617-5e92-5951-8a25-f55e620590f7'::uuid, 3, 'redaction', $exo${"titre":"Le sport est-il devenu trop cher ?","consigne":"Rédige une réponse argumentée, avec des exemples précis tirés du cours.","enonce":"Un supporter dit : *« Le football est devenu un business : l’argent des propriétaires et de la télévision a tout gâté. Il faudrait que les clubs puissent dépenser sans limite pour acheter les meilleurs joueurs. »*\n\nRédige une réponse argumentée qui : **(1)** présente les sources de revenus du sport en utilisant au moins trois exemples chiffrés ou datés ; **(2)** analyse les risques d’une dépense sans limite (propriétaires, inégalité) et les règles qui existent ; **(3)** évoque les écarts de salaires et les enjeux des paris sportifs.","bareme":[{"critere":"Au moins trois exemples précis (Mediapro 2020, DAZN, Ligue 1+, Neymar 222 M€ en 2017, PSG et Qatar depuis 2011, Premier League)","points":7},{"critere":"Risque d’inégalité de la compétition ; durabilité financière de l’UEFA","points":5},{"critere":"Écarts de salaires (stars/amateurs, hommes/femmes) ; paris sportifs, e-sport et protection des jeunes","points":5},{"critere":"Argumentation structurée et conclusion nuancée","points":3}],"dureeMin":15,"corrige":"**Réponse attendue.** Le sport vit de plusieurs sources : **droits TV**, **sponsors et équipementiers** (Nike, Adidas), **billetterie**, **transferts** et **propriétaires**. En France, la télévision reste fragile : **Mediapro** fait faillite en **2020**, **DAZN** diffuse en 2024-25, puis la Ligue lance **Ligue 1+** en 2025 ; la **Premier League** anglaise est bien plus riche. Le record de transfert est celui de **Neymar**, **222 millions d’euros** en **2017**, et le **PSG** appartient au **Qatar depuis 2011** : des clubs sont détenus par des États ou des fonds.\n\nMais une dépense sans limite est dangereuse : quand l’argent d’un propriétaire est illimité, la **compétition devient inégale**. C’est pourquoi l’**UEFA** impose des règles de **durabilité financière** : un club ne doit pas dépenser durablement plus qu’il ne gagne.\n\nLes **écarts de salaires** sont immenses, entre **stars et amateurs** et entre **hommes et femmes** : la majorité des sportifs ne vivent pas de leur sport. Enfin, les **paris sportifs** et l’**e-sport** sont en plein essor et posent la question de l’**addiction** et de la **protection des plus jeunes**. **Conclusion** : l’argent fait vivre le sport, mais il doit être encadré pour ne pas fausser la compétition."}$exo$::jsonb),
  ('790c7652-158b-53ec-9d7b-a46425575c02'::uuid, 1, 'redaction', $exo${"titre":"Qu’est-ce que le dopage ?","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Définis le **dopage**. À quelle fréquence la liste des produits interdits est-elle mise à jour ?\n2. Que s’est-il passé en 1998 sur le Tour de France ?\n3. Nomme l’organisme mondial créé en 1999 (siège, rôle) et l’organisme français créé en 2006.","bareme":[{"critere":"Dopage : substances ou méthodes interdites pour améliorer artificiellement la performance ; liste mise à jour chaque année","points":7},{"critere":"Affaire Festina de 1998 : produits dopants trouvés chez un soigneur, Willy Voet, crise du Tour","points":6},{"critere":"AMA (Montréal, Code mondial antidopage) ; AFLD en 2006","points":7}],"dureeMin":7,"corrige":"1. Le **dopage** est l’usage de **substances ou de méthodes interdites** pour améliorer artificiellement ses performances. La liste est **mise à jour chaque année**. Se doper, c’est tricher et mettre sa santé en danger.\n\n2. En 1998, la police trouve des centaines de produits dopants dans la voiture d’un soigneur de l’équipe **Festina** (**Willy Voet**) : c’est l’**affaire Festina**, qui plonge le Tour de France dans la crise.\n\n3. L’**AMA** (Agence mondiale antidopage), créée en **1999**, siège à **Montréal** et édicte le **Code mondial antidopage**. En France, l’**AFLD** (Agence française de lutte contre le dopage) date de **2006**."}$exo$::jsonb),
  ('790c7652-158b-53ec-9d7b-a46425575c02'::uuid, 2, 'redaction', $exo${"titre":"Le contrôle d’un athlète","consigne":"Lis la situation, puis réponds de façon rédigée et justifiée.","enonce":"Situation : Julie, 17 ans, cycliste de haut niveau, doit indiquer chaque jour où elle se trouve. Un matin, des contrôleurs se présentent à l’improviste. Plus tard, son entraîneur lui propose un « complément naturel » acheté sur internet, sans notice précise.\n\n1. Nomme les **dispositifs** de contrôle mentionnés (inopinés, localisation) et le suivi des valeurs sanguines dans la durée.\n2. Quelle est la **sanction habituelle** en cas de contrôle positif ?\n3. Pourquoi ce complément est-il risqué ? Que dit le cours de la responsabilité de l’athlète ?\n4. Julie est malade et doit prendre un médicament interdit : que peut-elle demander ?","bareme":[{"critere":"Contrôles inopinés, localisation (ADAMS), passeport biologique","points":6},{"critere":"Sanction habituelle de 4 ans de suspension","points":3},{"critere":"Compléments pouvant contenir des substances dopantes ; contrôle positif involontaire ; athlète toujours responsable","points":7},{"critere":"AUT : autorisation à usage thérapeutique après examen par un médecin","points":4}],"dureeMin":12,"corrige":"1. Les **contrôles inopinés** ; la **localisation** (l’athlète indique où elle se trouve, via le système **ADAMS**) ; le **passeport biologique**, qui suit ses valeurs sanguines dans le temps pour repérer les anomalies.\n\n2. La sanction habituelle est de **4 ans de suspension**.\n\n3. Certains **compléments alimentaires** contiennent des **substances interdites non étiquetées**. Dire « je ne savais pas » ne protège pas : un contrôle positif « involontaire » reste un contrôle positif, car l’athlète est **toujours responsable de ce qu’il avale**.\n\n4. Elle peut demander une **AUT** (autorisation à usage thérapeutique), qui lui permet de prendre légalement le médicament après **examen par un médecin**."}$exo$::jsonb),
  ('790c7652-158b-53ec-9d7b-a46425575c02'::uuid, 3, 'redaction', $exo${"titre":"Pourquoi ça ne vaut pas le coup","consigne":"Rédige une réponse argumentée, avec des exemples précis tirés du cours.","enonce":"Un jeune sportif dit : *« Tout le monde se dope un peu, c’est le seul moyen de gagner. Et puis, si on ne se fait pas prendre, il n’y a aucun risque. »*\n\nRédige une réponse argumentée qui : **(1)** explique pourquoi on triche (pression, argent, peur) en s’appuyant sur au moins trois affaires datées ; **(2)** montre comment la lutte antidopage s’est organisée (AMA, contrôles, passeport biologique) ; **(3)** démontre que « ça ne vaut pas le coup » : risques pour la santé, la carrière et l’honneur.","bareme":[{"critere":"Au moins trois affaires datées (Simpson 1967, Johnson 1988, Festina 1998, Armstrong 2012, Russie 2016) et causes de la triche","points":6},{"critere":"Organisation de la lutte : AMA 1999, AFLD 2006, contrôles inopinés, ADAMS, passeport biologique, sanction de 4 ans","points":6},{"critere":"Triple risque : santé (EPO, anabolisants, hormone de croissance), carrière, honneur","points":5},{"critere":"Argumentation structurée et conclusion","points":3}],"dureeMin":15,"corrige":"**Réponse attendue.** Ce n’est pas vrai que « tout le monde » se dope, et le risque est bien réel. Si certains trichent, c’est par la **pression de gagner**, l’**argent** et la **peur d’échouer**. L’histoire en donne des exemples : **Tom Simpson** meurt sur le Ventoux (**1967**), **Ben Johnson** est déclassé après son 100 m à Séoul (**1988**), l’affaire **Festina** secoue le Tour (**1998**), **Lance Armstrong** est déchu de ses titres (**2012**), le rapport **McLaren** révèle un dopage d’État en Russie (**2016**).\n\nLa lutte s’est organisée : l’**AMA** est créée en **1999** (siège à Montréal) et édicte le **Code mondial antidopage** ; en France l’**AFLD** date de **2006**. Les athlètes subissent des **contrôles inopinés**, doivent indiquer où ils se trouvent (**ADAMS**), et le **passeport biologique** suit leurs valeurs sanguines pour repérer les anomalies. La sanction habituelle est de **4 ans** de suspension. Le contrôle ne se contente pas de chercher un produit : il suit le corps dans la durée.\n\nEnfin, le risque est triple. Pour la **santé** : l’**EPO** rend le sang plus épais (risque cardiaque), les **anabolisants** abîment cœur, foie et système hormonal, l’**hormone de croissance** dérègle l’organisme ; des sportifs en sont morts. Pour la **carrière** : suspension, titres retirés (ceux d’Armstrong l’ont été). Pour l’**honneur** : le tricheur perd la confiance de tous. Même le dopage « involontaire » par un complément contaminé est sanctionné. **Conclusion** : le dopage est de la triche, il met en danger la santé et la carrière, et il ne vaut pas le coup."}$exo$::jsonb)
) AS v (chapter_id, difficulte, style, contenu)
JOIN public.chapters c ON c.id = v.chapter_id
ON CONFLICT (id) DO UPDATE
  SET style      = EXCLUDED.style,
      contenu    = EXCLUDED.contenu,
      difficulte = EXCLUDED.difficulte,
      origine    = 'catalogue';

DO $$
DECLARE
  n INT;
BEGIN
  SELECT count(*) INTO n
    FROM public.chapter_exercices e
   WHERE e.origine = 'catalogue'
     AND e.chapter_id IN ('b6124e13-4abd-5a43-8fbb-7e9992ff56b7', '18025266-7610-5538-8081-e77ac4ab711c', '21dd452b-bb68-53aa-990d-5157740fdf42', 'f1bc637c-5cea-5b98-981c-23940f3e3230', 'e270f3b1-967c-5a19-9e3c-05e83ee12861', '78dffff4-cbfc-5911-95cb-6520d0db2c2d', 'e37c9cb1-203b-566b-b39b-917ad4cb95c6', 'b0e6ec43-5992-585f-9768-bd8583076743', 'fa152617-5e92-5951-8a25-f55e620590f7', '790c7652-158b-53ec-9d7b-a46425575c02');
  RAISE NOTICE '574 : % sujets au catalogue (attendu : 30)', n;
  IF n < 30 THEN
    RAISE WARNING '574 : il manque des sujets — des fiches ont-elles changé d''identifiant ?';
  END IF;
END $$;
